window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["ROM"]={"book":"ROM","editions":{"fin-biblia1776":[[1,1,"Paavali, Jesuksen Kristuksen palvelia, kutsuttu apostoliksi, eroitettu Jumalan evankeliumiin,","Paavali, Jesuksen Kristuksen palvelia, kutsuttu apostoliksi, eroitettu Jumalan evankeliumiin,"],[1,2,"(Jonka hän on ennen prophetainsa kautta pyhissä Raamatuissa luvannut,)","(Jonka hän on ennen prophetainsa kautta pyhissä Raamatuissa luvannut,)"],[1,3,"Hänen Pojassansa, (joka on Davidin siemenestä lihan puolesta syntynyt,","Hänen Pojassansa, (joka on Davidin siemenestä lihan puolesta syntynyt,"],[1,4,"Ja on väkevästi ilmoitettu Jumalan Pojaksi pyhityksen hengen jälkeen, että hän on noussut ylös kuolleista,) se on, Jesuksesta Kristuksesta meidän Herrastamme,","Ja on väkevästi ilmoitettu Jumalan Pojaksi pyhityksen hengen jälkeen, että hän on noussut ylös kuolleista,) se on, Jesuksesta Kristuksesta meidän Herrastamme,"],[1,5,"Jonka kautta me olemme armon ja apostolin viran saaneet, uskon kuuliaisuudeksi, kaikkein pakanain seassa, hänen nimensä päälle,","Jonka kautta me olemme armon ja apostolin viran saaneet, uskon kuuliaisuudeksi, kaikkein pakanain seassa, hänen nimensä päälle,"],[1,6,"Joista tekin olette Jesuksen Kristuksen kutsutut:","Joista tekin olette Jesuksen Kristuksen kutsutut:"],[1,7,"Kaikille, jotka Roomissa ovat, Jumalan rakkaille ja kutsutuille pyhille: armo olkoon teidän kanssanne, ja rauha Jumalalta meidän Isältämme ja Herralta Jesukselta Kristukselta!","Kaikille, jotka Roomissa ovat, Jumalan rakkaille ja kutsutuille pyhille: armo olkoon teidän kanssanne, ja rauha Jumalalta meidän Isältämme ja Herralta Jesukselta Kristukselta!"],[1,8,"Ensin kiitän minä Jumalaani, Jesuksen Kristuksen kautta, teidän kaikkein tähtenne, että teidän uskoanne kaikessa maailmassa mainitaan.","Ensin kiitän minä Jumalaani, Jesuksen Kristuksen kautta, teidän kaikkein tähtenne, että teidän uskoanne kaikessa maailmassa mainitaan."],[1,9,"Sillä Jumala on minun todistajani, jota minä hengessäni hänen Poikansa evankeliumissa palvelen, että minä lakkaamatta teitä muistan,","Sillä Jumala on minun todistajani, jota minä hengessäni hänen Poikansa evankeliumissa palvelen, että minä lakkaamatta teitä muistan,"],[1,10,"Rukoillen aina minun rukouksissani, että minä saisin jollakin tavalla vihdoin joskus, jos Jumala tahtoo, onnellisen tien tulla teidän tykönne.","Rukoillen aina minun rukouksissani, että minä saisin jollakin tavalla vihdoin joskus, jos Jumala tahtoo, onnellisen tien tulla teidän tykönne."],[1,11,"Sillä minä ikävöitsen teitä nähdä, että minä jotain hengellistä lahjaa teille jakaisin, että te vahvistetuksi tulisitte,","Sillä minä ikävöitsen teitä nähdä, että minä jotain hengellistä lahjaa teille jakaisin, että te vahvistetuksi tulisitte,"],[1,12,"Se on, että minä saisin ynnä teidän kanssanne lohdutuksen, uskon kautta, joka meillä keskenämme on, sekä teidän että minun.","Se on, että minä saisin ynnä teidän kanssanne lohdutuksen, uskon kautta, joka meillä keskenämme on, sekä teidän että minun."],[1,13,"Mutta en minä tahdo salata teiltä, rakkaat veljet, että minä olen usein aikonut tulla teidän tykönne, (ja olen tähän asti estetty) että minä teidänkin seassanne jonkun hedelmän saisin, niinkuin muidenkin pakanain seassa.","Mutta en minä tahdo salata teiltä, rakkaat veljet, että minä olen usein aikonut tulla teidän tykönne, (ja olen tähän asti estetty) että minä teidänkin seassanne jonkun hedelmän saisin, niinkuin muidenkin pakanain seassa."],[1,14,"Minä olen velkapää Grekiläisille ja muukalaisille, viisaille ja tyhmille.","Minä olen velkapää Grekiläisille ja muukalaisille, viisaille ja tyhmille."],[1,15,"Sentähden niin paljo kuin minussa on, olen minä teillekin, jotka Roomissa olette, valmis evankeliumia saarnaamaan.","Sentähden niin paljo kuin minussa on, olen minä teillekin, jotka Roomissa olette, valmis evankeliumia saarnaamaan."],[1,16,"Sillä en minä häpee Kristuksen evankeliumia; sillä se on Jumalan voima itsekullekin uskovaiselle autuudeksi. Ensin Juudalaiselle, niin myös Grekiläiselle.","Sillä en minä häpee Kristuksen evankeliumia; sillä se on Jumalan voima itsekullekin uskovaiselle autuudeksi. Ensin Juudalaiselle, niin myös Grekiläiselle."],[1,17,"Sillä siinä se vanhurskaus, joka Jumalan edessä kelpaa, ilmoitetaan uskosta uskoon, niinkuin kirjoitettu on: vanhurskaan pitää elämän uskosta.","Sillä siinä se vanhurskaus, joka Jumalan edessä kelpaa, ilmoitetaan uskosta uskoon, niinkuin kirjoitettu on: vanhurskaan pitää elämän uskosta."],[1,18,"Sillä Jumalan viha ilmestyy taivaasta kaiken ihmisten jumalattomuuden ja vääryyden tähden, jotka totuuden vääryydessä pitävät.","Sillä Jumalan viha ilmestyy taivaasta kaiken ihmisten jumalattomuuden ja vääryyden tähden, jotka totuuden vääryydessä pitävät."],[1,19,"Sentähden se, mikä taidetaan Jumalasta tuta, on heille tiettävä; sillä Jumala ilmoitti sen heille.","Sentähden se, mikä taidetaan Jumalasta tuta, on heille tiettävä; sillä Jumala ilmoitti sen heille."],[1,20,"Sillä hänen näkymättömät menonsa, nimittäin, ijankaikkinen voimansa ja jumaluutensa nähdään hamasta maailman luomisesta, jotka ymmärretään niistä, jotka tehdyt ovat: ettei he taitaisi itseänsä syyttömiksi sanoa.","Sillä hänen näkymättömät menonsa, nimittäin, ijankaikkinen voimansa ja jumaluutensa nähdään hamasta maailman luomisesta, jotka ymmärretään niistä, jotka tehdyt ovat: ettei he taitaisi itseänsä syyttömiksi sanoa."],[1,21,"Että he tunsivat Jumalan, ja ei ylistäneet häntä niinkuin Jumalaa eikä kiittäneet, vaan vilpistelivät omissa ajatuksissansa, ja heidän järjetöin sydämensä on pimennyt.","Että he tunsivat Jumalan, ja ei ylistäneet häntä niinkuin Jumalaa eikä kiittäneet, vaan vilpistelivät omissa ajatuksissansa, ja heidän järjetöin sydämensä on pimennyt."],[1,22,"Kuin he itsensä viisaiksi luulivat, niin he ovat tyhmiksi tulleet,","Kuin he itsensä viisaiksi luulivat, niin he ovat tyhmiksi tulleet,"],[1,23,"Ja ovat katoomattoman Jumalan kunnian muuttaneet katoovaisen ihmisen ja lintuin ja neljäjalkaisten ja matelevaisten kuvan muotoiseksi.","Ja ovat katoomattoman Jumalan kunnian muuttaneet katoovaisen ihmisen ja lintuin ja neljäjalkaisten ja matelevaisten kuvan muotoiseksi."],[1,24,"Sentähden on myös Jumala heidät laskenut sydämensä himoihin, saastauteen, häpäisemään keskenänsä omaa ruumistansa,","Sentähden on myös Jumala heidät laskenut sydämensä himoihin, saastauteen, häpäisemään keskenänsä omaa ruumistansa,"],[1,25,"Jotka Jumalan totuuden ovat valheeksi muuttaneet ja ovat kunnioittaneet ja palvelleet enemmän luontokappaletta kuin Luojaa, joka on siunattu ijankaikkisesti, amen!","Jotka Jumalan totuuden ovat valheeksi muuttaneet ja ovat kunnioittaneet ja palvelleet enemmän luontokappaletta kuin Luojaa, joka on siunattu ijankaikkisesti, amen!"],[1,26,"Sentähden on Jumala heidät antanut ylön häpiällisiin himoihin, että myös heidän vaimonsa ovat muuttaneet luonnollisen tavan luontoa vastaan,","Sentähden on Jumala heidät antanut ylön häpiällisiin himoihin, että myös heidän vaimonsa ovat muuttaneet luonnollisen tavan luontoa vastaan,"],[1,27,"Niin myös miehet ovat antaneet ylön vaimon luonnollisen pitämisen, toinen toisensa puoleen himoissansa palaneet, miehet miesten kanssa riettauden tehneet ja saaneet, niinkuin pitikin, eksymisensä palkan itsessänsä.","Niin myös miehet ovat antaneet ylön vaimon luonnollisen pitämisen, toinen toisensa puoleen himoissansa palaneet, miehet miesten kanssa riettauden tehneet ja saaneet, niinkuin pitikin, eksymisensä palkan itsessänsä."],[1,28,"Ja niinkuin ei he tahtoneet Jumalaa tuta, niin Jumala laski heidät häijyyn mieleen tekemään niitä, mitä ei sovi tehdä,","Ja niinkuin ei he tahtoneet Jumalaa tuta, niin Jumala laski heidät häijyyn mieleen tekemään niitä, mitä ei sovi tehdä,"],[1,29,"Täynnänsä kaikkea vääryyttä, salavuoteutta, koiruutta, ahneutta, pahuutta: täynnä kateutta, murhaa, riitaa, petosta, pahan suomuutta:","Täynnänsä kaikkea vääryyttä, salavuoteutta, koiruutta, ahneutta, pahuutta: täynnä kateutta, murhaa, riitaa, petosta, pahan suomuutta:"],[1,30,"Korvankuiskutteliat, panetteliat, Jumalaa vihaajat, häpäisiät, ylpiät öykkärit, pahain neuvoin pesät, vanhemmillensa tottelemattomat,","Korvankuiskutteliat, panetteliat, Jumalaa vihaajat, häpäisiät, ylpiät öykkärit, pahain neuvoin pesät, vanhemmillensa tottelemattomat,"],[1,31,"Tomppelit, liiton rikkojat, haluttomat, sovittamattomat, armottomat.","Tomppelit, liiton rikkojat, haluttomat, sovittamattomat, armottomat."],[1,32,"Jotka Jumalan oikeuden tietävät, (että ne, jotka näitä tekevät, ovat kuoleman ansainneet) ei ainoastaan niitä tee, mutta myös suostuvat niihin, jotka niitä tekevät.","Jotka Jumalan oikeuden tietävät, (että ne, jotka näitä tekevät, ovat kuoleman ansainneet) ei ainoastaan niitä tee, mutta myös suostuvat niihin, jotka niitä tekevät."],[2,1,"Sentähden, oi ihminen, et sinä taida itsiäs syyttömäksi tehdä, vaikka kuka sinä olet, joka tuomitset; sillä jossa sinä toista tuomitset, siinä sinä itses tuomitset, ettäs niitä teet, joita sinä tuomitset.","Sentähden, oi ihminen, et sinä taida itsiäs syyttömäksi tehdä, vaikka kuka sinä olet, joka tuomitset; sillä jossa sinä toista tuomitset, siinä sinä itses tuomitset, ettäs niitä teet, joita sinä tuomitset."],[2,2,"Mutta me tiedämme, että Jumalan tuomio on oikia niiden ylitse, jotka senkaltaisia tekevät.","Mutta me tiedämme, että Jumalan tuomio on oikia niiden ylitse, jotka senkaltaisia tekevät."],[2,3,"Eli luuletkos, ihminen, sinä joka niitä tuomitset, jotka senkaltaisia tekevät, ja itse myös niitä teet, että sinä vältät Jumalan tuomion?","Eli luuletkos, ihminen, sinä joka niitä tuomitset, jotka senkaltaisia tekevät, ja itse myös niitä teet, että sinä vältät Jumalan tuomion?"],[2,4,"Eli katsotkos ylön hänen hyvyytensä, kärsiväisyytensä ja pitkämielisyytensä rikkauden, ettet tiedä, että Jumalan hyvyys vetää sinua parannukseen?","Eli katsotkos ylön hänen hyvyytensä, kärsiväisyytensä ja pitkämielisyytensä rikkauden, ettet tiedä, että Jumalan hyvyys vetää sinua parannukseen?"],[2,5,"Mutta kovuutes ja katumattoman sydämes jälkeen kartutat sinä vihan itselles vihan päivänä, kuin Jumalan oikia tuomio ilmaantuu,","Mutta kovuutes ja katumattoman sydämes jälkeen kartutat sinä vihan itselles vihan päivänä, kuin Jumalan oikia tuomio ilmaantuu,"],[2,6,"Joka antaa itsekullekin hänen töittensä jälkeen,","Joka antaa itsekullekin hänen töittensä jälkeen,"],[2,7,"Niille, jotka pyytävät ylistystä, kunniaa ja katoomatointa menoa kärsiväisyydellä hyvissä töissä, ijankaikkisen elämän;","Niille, jotka pyytävät ylistystä, kunniaa ja katoomatointa menoa kärsiväisyydellä hyvissä töissä, ijankaikkisen elämän;"],[2,8,"Mutta niille, jotka riitaiset ovat, eikä kuule totuutta, vaan kuulevat vääryyttä, on tuleva närkästys ja viha.","Mutta niille, jotka riitaiset ovat, eikä kuule totuutta, vaan kuulevat vääryyttä, on tuleva närkästys ja viha."],[2,9,"Murhe ja vaiva kunkin ihmisen sielun päälle, joka pahaa tekee, ensisti Juudalaisen, niin myös Grekiläisen;","Murhe ja vaiva kunkin ihmisen sielun päälle, joka pahaa tekee, ensisti Juudalaisen, niin myös Grekiläisen;"],[2,10,"Mutta ylistys, kunnia ja rauha jokaiselle, joka hyvää tekee, ensisti Juudalaiselle, niin myös Grekiläiselle.","Mutta ylistys, kunnia ja rauha jokaiselle, joka hyvää tekee, ensisti Juudalaiselle, niin myös Grekiläiselle."],[2,11,"Sillä ei Jumala katso ihmisen muodon jälkeen.","Sillä ei Jumala katso ihmisen muodon jälkeen."],[2,12,"Kaikki, jotka ilman lakia ovat syntiä tehneet, niiden pitää myös ilman lakia hukkuman, ja kaikki, jotka laissa ovat syntiä tehneet, ne pitää lain kautta tuomittaman.","Kaikki, jotka ilman lakia ovat syntiä tehneet, niiden pitää myös ilman lakia hukkuman, ja kaikki, jotka laissa ovat syntiä tehneet, ne pitää lain kautta tuomittaman."],[2,13,"Sillä ei ne ole Jumalan edessä vanhurskaat, jotka lain kuulevat; mutta ne, jotka lain töillänsä täyttävät, ne pitää vanhurskaaksi tuleman.","Sillä ei ne ole Jumalan edessä vanhurskaat, jotka lain kuulevat; mutta ne, jotka lain töillänsä täyttävät, ne pitää vanhurskaaksi tuleman."],[2,14,"Sillä koska pakanat, joilla ei lakia ole, tekevät luonnostansa sitä, mitä laki anoo, niin he, vaikka ei heillä lakia ole, ovat itsellensä laki,","Sillä koska pakanat, joilla ei lakia ole, tekevät luonnostansa sitä, mitä laki anoo, niin he, vaikka ei heillä lakia ole, ovat itsellensä laki,"],[2,15,"Että he osoittavat lain työn olevan kirjoitetun sydämiinsä, ja niin heidän omatuntonsa ynnä todistaa, ja heidän ajatuksensa keskenänsä itse päällensä kantavat eli myös heitänsä syyttömäksi tekevät,","Että he osoittavat lain työn olevan kirjoitetun sydämiinsä, ja niin heidän omatuntonsa ynnä todistaa, ja heidän ajatuksensa keskenänsä itse päällensä kantavat eli myös heitänsä syyttömäksi tekevät,"],[2,16,"Sinä päivänä, jona Jumala ihmisten salaisuudet on tuomitseva, minun evankeliumini perästä Jesuksen Kristuksen kautta.","Sinä päivänä, jona Jumala ihmisten salaisuudet on tuomitseva, minun evankeliumini perästä Jesuksen Kristuksen kautta."],[2,17,"Katso, sinä kutsutaan Juudalaiseksi, ja sinä luotat lakiin ja kerskaat Jumalasta,","Katso, sinä kutsutaan Juudalaiseksi, ja sinä luotat lakiin ja kerskaat Jumalasta,"],[2,18,"Ja tiedät hänen tahtonsa, ja että sinä olet laista neuvottu, niin sinä koettelet ne parhaat,","Ja tiedät hänen tahtonsa, ja että sinä olet laista neuvottu, niin sinä koettelet ne parhaat,"],[2,19,"Ja luulet itses sokiain johdattajaksi ja niiden valkeudeksi, jotka pimeydessä ovat,","Ja luulet itses sokiain johdattajaksi ja niiden valkeudeksi, jotka pimeydessä ovat,"],[2,20,"Ja tyhmäin kurittajaksi, ja lasten opettajaksi, ja sinullas olevan tunnon ja totuuden muodon laissa.","Ja tyhmäin kurittajaksi, ja lasten opettajaksi, ja sinullas olevan tunnon ja totuuden muodon laissa."],[2,21,"Sinä joka siis opetat toista ja et itsiäs opeta; joka saarnaat: ei pidä varastaman, ja sinä itse varastat;","Sinä joka siis opetat toista ja et itsiäs opeta; joka saarnaat: ei pidä varastaman, ja sinä itse varastat;"],[2,22,"Joka sanot: ei pidä huorin tehtämän, ja sinä itse teet huorin; joka kauhistut epäjumalia, ja raatelet sitä Jumalalta, mikä hänelle tulee;","Joka sanot: ei pidä huorin tehtämän, ja sinä itse teet huorin; joka kauhistut epäjumalia, ja raatelet sitä Jumalalta, mikä hänelle tulee;"],[2,23,"Joka kerskaat laista ja häpäiset Jumalaa lain ylitsekäymisellä?","Joka kerskaat laista ja häpäiset Jumalaa lain ylitsekäymisellä?"],[2,24,"Sillä teidän tähtenne tulee Jumalan nimi pilkatuksi pakanain seassa, niinkuin kirjoitettu on.","Sillä teidän tähtenne tulee Jumalan nimi pilkatuksi pakanain seassa, niinkuin kirjoitettu on."],[2,25,"Sillä ympärileikkaus kelpaa, jos sinä lain pidät; mutta jos sinä olet lain rikkoja, niin sinun ympärileikkaukses on esinahaksi tullut.","Sillä ympärileikkaus kelpaa, jos sinä lain pidät; mutta jos sinä olet lain rikkoja, niin sinun ympärileikkaukses on esinahaksi tullut."],[2,26,"Jos siis esinahka lain oikeuden pitää, eikö hänen esinahkansa pidä luettaman hänelle ympärileikkaukseksi?","Jos siis esinahka lain oikeuden pitää, eikö hänen esinahkansa pidä luettaman hänelle ympärileikkaukseksi?"],[2,27,"Ja se joka luonnostansa esinahka on ja täyttää lain, pitää sinun tuomitseman, joka puustavin ja ympärileikkauksen lain käyt ylitse?","Ja se joka luonnostansa esinahka on ja täyttää lain, pitää sinun tuomitseman, joka puustavin ja ympärileikkauksen lain käyt ylitse?"],[2,28,"Sillä ei se ole Juudalainen, joka ulkonaisesti (Juudalainen) on: ei myös se ole ympärileikkaus, mikä ulkonaisessa lihassa tapahtuu;","Sillä ei se ole Juudalainen, joka ulkonaisesti (Juudalainen) on: ei myös se ole ympärileikkaus, mikä ulkonaisessa lihassa tapahtuu;"],[2,29,"Mutta se on Juudalainen, joka sisällisesti salattu on, ja sydämen ympärileikkaus on ympärileikkaus, joka hengessä tapahtuu, ei puustavissa; jonka ylistys ei ole ihmisiltä, vaan Jumalalta.","Mutta se on Juudalainen, joka sisällisesti salattu on, ja sydämen ympärileikkaus on ympärileikkaus, joka hengessä tapahtuu, ei puustavissa; jonka ylistys ei ole ihmisiltä, vaan Jumalalta."],[3,1,"Mitäs siis Juudalainen on parempi? Eli mitä ympärileikkaus auttaa?","Mitäs siis Juudalainen on parempi? Eli mitä ympärileikkaus auttaa?"],[3,2,"Tosin sangen paljo. Sillä ensin on se, että heille on uskottu, mitä Jumala puhunut on.","Tosin sangen paljo. Sillä ensin on se, että heille on uskottu, mitä Jumala puhunut on."],[3,3,"Mutta ettei muutamat niitä uskoneet, mikä siitä on? Pitäiskö heidän epäuskonsa Jumalan uskon turhaksi tekemän?","Mutta ettei muutamat niitä uskoneet, mikä siitä on? Pitäiskö heidän epäuskonsa Jumalan uskon turhaksi tekemän?"],[3,4,"Pois se! vaan paremmin, olkoon Jumala totinen, vaan jokainen ihminen valehtelia, niinkuin kirjoitettu on: ettäs olisit oikia sanoissas ja voittaisit, kuin sinä tuomitaan.","Pois se! vaan paremmin, olkoon Jumala totinen, vaan jokainen ihminen valehtelia, niinkuin kirjoitettu on: ettäs olisit oikia sanoissas ja voittaisit, kuin sinä tuomitaan."],[3,5,"Jos siis meidän vääryytemme Jumalan oikeutta ylistää, mitäs me sanomme? Onko Jumala väärä, että hän siitä vihastuu? (minä puhun ihmisten tavalla.)","Jos siis meidän vääryytemme Jumalan oikeutta ylistää, mitäs me sanomme? Onko Jumala väärä, että hän siitä vihastuu? (minä puhun ihmisten tavalla.)"],[3,6,"Pois se! kuinka Jumala sitte taitais maailmaa tuomita?","Pois se! kuinka Jumala sitte taitais maailmaa tuomita?"],[3,7,"Sillä jos Jumalan totuus minun valheeni kautta kunniallisemmaksi tulis, hänen ylistykseksensä, minkätahden pitäis vielä sitte minä niinkuin syntinen tuomittaman?","Sillä jos Jumalan totuus minun valheeni kautta kunniallisemmaksi tulis, hänen ylistykseksensä, minkätahden pitäis vielä sitte minä niinkuin syntinen tuomittaman?"],[3,8,"Ja ei, (niinkuin meitä pilkataan ja niinkuin muutamat puhuvat meidän sanovan,) että meidän pitäis tekemän pahaa, että siitä hyvää tulis? Joiden kadotus on oikia.","Ja ei, (niinkuin meitä pilkataan ja niinkuin muutamat puhuvat meidän sanovan,) että meidän pitäis tekemän pahaa, että siitä hyvää tulis? Joiden kadotus on oikia."],[3,9,"Mitäs siis? Olemmeko me paremmat kuin he? Emme ensinkään; sillä me olemme ennen osoittaneet, että sekä Juudalaiset ja Grekiläiset ovat kaikki synnin alla,","Mitäs siis? Olemmeko me paremmat kuin he? Emme ensinkään; sillä me olemme ennen osoittaneet, että sekä Juudalaiset ja Grekiläiset ovat kaikki synnin alla,"],[3,10,"Niinkuin kirjoitettu on: ei ole kenkään vanhurskas, ei yksikään;","Niinkuin kirjoitettu on: ei ole kenkään vanhurskas, ei yksikään;"],[3,11,"Ei ole yhtäkään ymmärtäväistä, ei ole ketään, joka etsii Jumalaa.","Ei ole yhtäkään ymmärtäväistä, ei ole ketään, joka etsii Jumalaa."],[3,12,"Kaikki ovat poikenneet pois ja ynnä kelvottomaksi tulleet: ei ole yhtään, joka hyvää tekee, ei yhtäkään.","Kaikki ovat poikenneet pois ja ynnä kelvottomaksi tulleet: ei ole yhtään, joka hyvää tekee, ei yhtäkään."],[3,13,"Heidän kurkkunsa on avoin hauta, kielellänsä he pettävät, kyykäärmeen myrkky on heidän huultensa alla,","Heidän kurkkunsa on avoin hauta, kielellänsä he pettävät, kyykäärmeen myrkky on heidän huultensa alla,"],[3,14,"Joiden suu on täynnänsä kirousta ja haikeutta.","Joiden suu on täynnänsä kirousta ja haikeutta."],[3,15,"Heidän jalkansa ovat nopiat verta vuodattamaan.","Heidän jalkansa ovat nopiat verta vuodattamaan."],[3,16,"Heidän teissänsä on sula tuska ja sydämen kipu.","Heidän teissänsä on sula tuska ja sydämen kipu."],[3,17,"Ja ei he rauhan tietä tunteneet.","Ja ei he rauhan tietä tunteneet."],[3,18,"Ei ole Jumalan pelko heidän silmäinsä edessä.","Ei ole Jumalan pelko heidän silmäinsä edessä."],[3,19,"Mutta sen me tiedämme, että kaikki, mitä laki sanoo, sen hän sanoo niille, jotka lain alla ovat: että jokainen suu pitää tukittaman ja kaiken maailman pitää Jumalan edessä vikapää oleman,","Mutta sen me tiedämme, että kaikki, mitä laki sanoo, sen hän sanoo niille, jotka lain alla ovat: että jokainen suu pitää tukittaman ja kaiken maailman pitää Jumalan edessä vikapää oleman,"],[3,20,"Sentähden ettei yksikään liha taida lain töiden kautta hänen edessänsä vanhurskautetuksi tulla; sillä lain kautta synnin tunto tulee.","Sentähden ettei yksikään liha taida lain töiden kautta hänen edessänsä vanhurskautetuksi tulla; sillä lain kautta synnin tunto tulee."],[3,21,"Mutta nyt on se vanhurskaus, joka Jumalan edessä kelpaa, ilman lakia julistettu, lain ja prophetain kautta todistettu;","Mutta nyt on se vanhurskaus, joka Jumalan edessä kelpaa, ilman lakia julistettu, lain ja prophetain kautta todistettu;"],[3,22,"Se Jumalan vanhurskaus, (sanon minä), joka tulee Jesuksen Kristuksen uskon kautta, kaikkein tykö ja kaikkein päälle, jotka uskovat: sillä ei ole yhtään eroitusta.","Se Jumalan vanhurskaus, (sanon minä), joka tulee Jesuksen Kristuksen uskon kautta, kaikkein tykö ja kaikkein päälle, jotka uskovat: sillä ei ole yhtään eroitusta."],[3,23,"Sillä kaikki ovat he syntiä tehneet ja ei heillä ole mitään kerskattavaa Jumalan edessä.","Sillä kaikki ovat he syntiä tehneet ja ei heillä ole mitään kerskattavaa Jumalan edessä."],[3,24,"He tulevat ilman ansiotansa vanhurskaaksi, hänen armostansa, sen lunastuksen kautta, joka on Jesuksessa Kristuksessa,","He tulevat ilman ansiotansa vanhurskaaksi, hänen armostansa, sen lunastuksen kautta, joka on Jesuksessa Kristuksessa,"],[3,25,"Jonka Jumala on armonistuimeksi asettanut, uskon kautta hänen veressänsä, osoittaaksensa sitä vanhurskautta, joka hänen edessänsä kelpaa, edelläkäyväisten syntein anteeksi antamisen kautta,","Jonka Jumala on armonistuimeksi asettanut, uskon kautta hänen veressänsä, osoittaaksensa sitä vanhurskautta, joka hänen edessänsä kelpaa, edelläkäyväisten syntein anteeksi antamisen kautta,"],[3,26,"Joita Jumala kärsinyt on, osoittaaksensa vanhurskauttansa tällä ajalla: että hän itse vanhurskas olis ja sen vanhurskaaksi tekis, joka Jesuksen uskosta on.","Joita Jumala kärsinyt on, osoittaaksensa vanhurskauttansa tällä ajalla: että hän itse vanhurskas olis ja sen vanhurskaaksi tekis, joka Jesuksen uskosta on."],[3,27,"Kussa siis on kerskaus? Se on suljettu ulos. Minkä lain kautta? Töidenkö lain kautta? Ei, vaan uskon lain kautta.","Kussa siis on kerskaus? Se on suljettu ulos. Minkä lain kautta? Töidenkö lain kautta? Ei, vaan uskon lain kautta."],[3,28,"Niin me siis sen siksi pidämme, että ihminen tulee vanhurskaaksi uskon kautta, ilman lain töitä.","Niin me siis sen siksi pidämme, että ihminen tulee vanhurskaaksi uskon kautta, ilman lain töitä."],[3,29,"Eli onko Jumala ainoastaan Juudalaisten Jumala? eikö hän ole myös pakanain Jumala? Tosin pakanainkin Jumala,","Eli onko Jumala ainoastaan Juudalaisten Jumala? eikö hän ole myös pakanain Jumala? Tosin pakanainkin Jumala,"],[3,30,"Että yksi on Jumala, joka ympärileikkauksen tekee vanhurskaaksi uskosta, ja esinahan uskon kautta.","Että yksi on Jumala, joka ympärileikkauksen tekee vanhurskaaksi uskosta, ja esinahan uskon kautta."],[3,31,"Teemmekö me lain tyhjäksi uskon kautta? Pois se; vaan me vahvistamme lain.","Teemmekö me lain tyhjäksi uskon kautta? Pois se; vaan me vahvistamme lain."],[4,1,"Mitäs me siis sanomme meidän isämme Abrahamin lihan puolesta löytäneen?","Mitäs me siis sanomme meidän isämme Abrahamin lihan puolesta löytäneen?"],[4,2,"Sillä jos Abraham on töiden kautta vanhurskaaksi tullut, niin hänellä on kerskaamista, vaan ei Jumalan edessä.","Sillä jos Abraham on töiden kautta vanhurskaaksi tullut, niin hänellä on kerskaamista, vaan ei Jumalan edessä."],[4,3,"Mutta mitä Raamattu sano: Abraham uskoi Jumalan, ja se luettiin hänelle vanhurskaudeksi.","Mutta mitä Raamattu sano: Abraham uskoi Jumalan, ja se luettiin hänelle vanhurskaudeksi."],[4,4,"Mutta sille, joka työtä tekee, ei lueta palkkaa armosta, vaan ansiosta.","Mutta sille, joka työtä tekee, ei lueta palkkaa armosta, vaan ansiosta."],[4,5,"Mutta joka ei työtä tee, vaan uskoo sen päälle, joka jumalattoman vanhurskaaksi tekee, hänen uskonsa luetaan hänelle vanhurskaudeksi.","Mutta joka ei työtä tee, vaan uskoo sen päälle, joka jumalattoman vanhurskaaksi tekee, hänen uskonsa luetaan hänelle vanhurskaudeksi."],[4,6,"Niinkuin myös David sanoo: autuus on sen ihmisen, jolle Jumala vanhurskauden lukee ilman töitä:","Niinkuin myös David sanoo: autuus on sen ihmisen, jolle Jumala vanhurskauden lukee ilman töitä:"],[4,7,"Autuaat ovat ne, joidenka vääryydet ovat anteeksi annetut, ja joidenka synnit peitetyt ovat.","Autuaat ovat ne, joidenka vääryydet ovat anteeksi annetut, ja joidenka synnit peitetyt ovat."],[4,8,"Autuas on se mies, jolle Jumala ei syntiä lue.","Autuas on se mies, jolle Jumala ei syntiä lue."],[4,9,"Lieneekö siis tämä autuus ainoastaan ympärileikkaukselle tullut, elikkä myös esinahalle? Niinpä me sanomme: Abrahamille luettiin usko vanhurskaudeksi.","Lieneekö siis tämä autuus ainoastaan ympärileikkaukselle tullut, elikkä myös esinahalle? Niinpä me sanomme: Abrahamille luettiin usko vanhurskaudeksi."],[4,10,"Kuinkas se hänelle luettiin: koska hän oli ympärileikkauksessa, eli esinahassa? Ei ympärileikkauksessa, vaan esinahassa,","Kuinkas se hänelle luettiin: koska hän oli ympärileikkauksessa, eli esinahassa? Ei ympärileikkauksessa, vaan esinahassa,"],[4,11,"Ja hän sai ympärileikkauksen merkin vahvistukseksi, että hän oli uskon kautta vanhurskaaksi tehty, joka hänellä esinahassa oli, että hänen piti oleman kaikkein uskovaisten isä esinahassa, että se niillekin vanhurskaudeksi luettaisiin,","Ja hän sai ympärileikkauksen merkin vahvistukseksi, että hän oli uskon kautta vanhurskaaksi tehty, joka hänellä esinahassa oli, että hänen piti oleman kaikkein uskovaisten isä esinahassa, että se niillekin vanhurskaudeksi luettaisiin,"],[4,12,"Ja hän tulis myös ympärileikkauksen isäksi, ei ainoasti niiden, jotka ympärileikatuista syntyneet ovat, mutta myös niiden, jotka sen uskon jälkiä vaeltavat, joka meidän isän Abrahamin esinahassa oli.","Ja hän tulis myös ympärileikkauksen isäksi, ei ainoasti niiden, jotka ympärileikatuista syntyneet ovat, mutta myös niiden, jotka sen uskon jälkiä vaeltavat, joka meidän isän Abrahamin esinahassa oli."],[4,13,"Sillä se lupaus, että hänen piti maailman perilliseksi tuleman, ei ole Abrahamille eikä hänen siemenellensä lain kautta tapahtunut, vaan uskon vanhurskauden kautta.","Sillä se lupaus, että hänen piti maailman perilliseksi tuleman, ei ole Abrahamille eikä hänen siemenellensä lain kautta tapahtunut, vaan uskon vanhurskauden kautta."],[4,14,"Sillä jos ne, jotka laista ovat, ovat perilliset, niin usko on turha ja lupaus on hukkaan tullut.","Sillä jos ne, jotka laista ovat, ovat perilliset, niin usko on turha ja lupaus on hukkaan tullut."],[4,15,"Sillä laki kehoittaa vihan; sillä kussa ei lakia ole, ei siellä ole myös ylitsekäymistä.","Sillä laki kehoittaa vihan; sillä kussa ei lakia ole, ei siellä ole myös ylitsekäymistä."],[4,16,"Sentähden tulee se uskosta, että sen pitää armosta oleman: että se lupaus pitää vahva oleman kaikelle siemenelle, ei sille ainoastaan, joka lain alla on, mutta myös sille, joka Abrahamin uskosta on, joka on meidän kaikkein isämme,","Sentähden tulee se uskosta, että sen pitää armosta oleman: että se lupaus pitää vahva oleman kaikelle siemenelle, ei sille ainoastaan, joka lain alla on, mutta myös sille, joka Abrahamin uskosta on, joka on meidän kaikkein isämme,"],[4,17,"(Niinkuin kirjoitettu on: minä asetin sinun monen pakanan isäksi) Jumalan edessä, jonka hän uskonut on, joka kuolleet eläväksi tekee ja kutsuu ne, jotka ei ole, niinkuin ne olisivat.","(Niinkuin kirjoitettu on: minä asetin sinun monen pakanan isäksi) Jumalan edessä, jonka hän uskonut on, joka kuolleet eläväksi tekee ja kutsuu ne, jotka ei ole, niinkuin ne olisivat."],[4,18,"Ja hän uskoo sen toivon, jossa ei toivoa ollut, että hänen piti oleman monen pakanan isän, sen jälkeen kuin hänelle sanottu oli: niin pitää sinun siemenes oleman.","Ja hän uskoo sen toivon, jossa ei toivoa ollut, että hänen piti oleman monen pakanan isän, sen jälkeen kuin hänelle sanottu oli: niin pitää sinun siemenes oleman."],[4,19,"Ja ei hän tullut heikoksi uskossa eikä katsonut kuollutta ruumistansa, ehkä hän jo lähes sadan ajastajan vanha oli, eikä Saaran kuollutta kohtua.","Ja ei hän tullut heikoksi uskossa eikä katsonut kuollutta ruumistansa, ehkä hän jo lähes sadan ajastajan vanha oli, eikä Saaran kuollutta kohtua."],[4,20,"Mutta ei hän epäillyt ensinkään Jumalan lupauksesta epäuskolla, vaan oli vahva uskossa ja antoi Jumalalle kunnian,","Mutta ei hän epäillyt ensinkään Jumalan lupauksesta epäuskolla, vaan oli vahva uskossa ja antoi Jumalalle kunnian,"],[4,21,"Ja oli täydellisesti vahva siitä, että mitä Jumala lupaa, sen hän myös voi tehdä.","Ja oli täydellisesti vahva siitä, että mitä Jumala lupaa, sen hän myös voi tehdä."],[4,22,"Sentähden se on myös hänelle vanhurskaudeksi luettu.","Sentähden se on myös hänelle vanhurskaudeksi luettu."],[4,23,"Niin ei se ole ainoastaan hänen tähtensä kirjoitettu, että se hänelle luettu oli,","Niin ei se ole ainoastaan hänen tähtensä kirjoitettu, että se hänelle luettu oli,"],[4,24,"Vaan myös meidän tähtemme, joille se myös pitää luettaman, kuin me sen päälle uskomme, joka meidän Herran Jesuksen kuolleista herätti,","Vaan myös meidän tähtemme, joille se myös pitää luettaman, kuin me sen päälle uskomme, joka meidän Herran Jesuksen kuolleista herätti,"],[4,25,"Joka meidän synteimme tähden on annettu ulos, ja meidän vanhurskauttamisemme tähden herätetty ylös.","Joka meidän synteimme tähden on annettu ulos, ja meidän vanhurskauttamisemme tähden herätetty ylös."],[5,1,"Että me siis olemme uskosta vanhurskaiksi tulleet, niin meillä on rauha Jumalan kanssa meidän Herran Jesuksen Kristuksen kautta,","Että me siis olemme uskosta vanhurskaiksi tulleet, niin meillä on rauha Jumalan kanssa meidän Herran Jesuksen Kristuksen kautta,"],[5,2,"Jonka kautta myös meillä oli tykökäymys uskossa tähän armoon, jossa me seisomme ja kerskaamme Jumalan kunnian toivosta.","Jonka kautta myös meillä oli tykökäymys uskossa tähän armoon, jossa me seisomme ja kerskaamme Jumalan kunnian toivosta."],[5,3,"Mutta ei ainoasti siitä, vaan me kerskaamme myös vaivoissa; sillä me tiedämme, että vaiva saattaa kärsivällisyyden,","Mutta ei ainoasti siitä, vaan me kerskaamme myös vaivoissa; sillä me tiedämme, että vaiva saattaa kärsivällisyyden,"],[5,4,"Mutta kärsivällisyys koettelemuksen, koettelemus toivon.","Mutta kärsivällisyys koettelemuksen, koettelemus toivon."],[5,5,"Mutta toivo ei anna häpiään tulla, että Jumalan rakkaus on vuodatettu meidän sydämiimme Pyhän Hengen kautta, joka meille annettu on.","Mutta toivo ei anna häpiään tulla, että Jumalan rakkaus on vuodatettu meidän sydämiimme Pyhän Hengen kautta, joka meille annettu on."],[5,6,"Sillä Kristus, kuin me vielä heikot olimme, on ajallansa jumalattomain edestä kuollut.","Sillä Kristus, kuin me vielä heikot olimme, on ajallansa jumalattomain edestä kuollut."],[5,7,"Tuskalla nyt joku kuolis vanhurskaan edestä, ehkä hyvän edestä mitämaks joku tohtis kuolla.","Tuskalla nyt joku kuolis vanhurskaan edestä, ehkä hyvän edestä mitämaks joku tohtis kuolla."],[5,8,"Mutta Jumala ylistää rakkauttansa meidän kohtaamme, että kuin me vielä syntiset olimme, on Kristus meidän edestämme kuollut.","Mutta Jumala ylistää rakkauttansa meidän kohtaamme, että kuin me vielä syntiset olimme, on Kristus meidän edestämme kuollut."],[5,9,"Niin me siis paljoa enemmin varjellaan hänen kauttansa vihan edestä, että me nyt hänen verensä kautta vanhurskaiksi tulleet olemme.","Niin me siis paljoa enemmin varjellaan hänen kauttansa vihan edestä, että me nyt hänen verensä kautta vanhurskaiksi tulleet olemme."],[5,10,"Sillä jos me Jumalan kanssa olimme sovitetut hänen Poikansa kuoleman kautta, kuin me vielä hänen vihollisensa olimme, paljoa ennemmin me autuaiksi tulemme hänen elämänsä kautta, että me sovitetut olemme.","Sillä jos me Jumalan kanssa olimme sovitetut hänen Poikansa kuoleman kautta, kuin me vielä hänen vihollisensa olimme, paljoa ennemmin me autuaiksi tulemme hänen elämänsä kautta, että me sovitetut olemme."],[5,11,"Mutta ei ainoasti siitä, vaan me kerskaamme myös Jumalasta, meidän Herran Jesuksen Kristuksen kautta, jonka kautta me nyt olemme sovinnon saaneet.","Mutta ei ainoasti siitä, vaan me kerskaamme myös Jumalasta, meidän Herran Jesuksen Kristuksen kautta, jonka kautta me nyt olemme sovinnon saaneet."],[5,12,"Sentähden, niinkuin yhden ihmisen kautta on synti maailmaan tullut ja synnin kautta kuolema, niin on kuolema tullut kaikkein ihmisten päälle, että kaikki ovat syntiä tehneet.","Sentähden, niinkuin yhden ihmisen kautta on synti maailmaan tullut ja synnin kautta kuolema, niin on kuolema tullut kaikkein ihmisten päälle, että kaikki ovat syntiä tehneet."],[5,13,"Sillä lakiin asti oli synti maailmassa; mutta kussa ei lakia ole, ei siellä syntiä lueta.","Sillä lakiin asti oli synti maailmassa; mutta kussa ei lakia ole, ei siellä syntiä lueta."],[5,14,"Vaan kuolema vallitsi Adamista Mosekseen asti niitäkin, jotka ei syntiä tehneet olleet senkaltaisella ylitsekäymisellä kuin Adam, joka on sen esikuva, joka jälkeen tuleva oli.","Vaan kuolema vallitsi Adamista Mosekseen asti niitäkin, jotka ei syntiä tehneet olleet senkaltaisella ylitsekäymisellä kuin Adam, joka on sen esikuva, joka jälkeen tuleva oli."],[5,15,"Mutta ei niin lahjan kanssa ole kuin synnin; sillä jos monta ovat sen yhden synnin tähden kuolleet, niin on paljoa enemmin Jumalan armo ja lahja sen yhden ihmisen Jesuksen Kristuksen armossa monen päälle runsaasti tullut.","Mutta ei niin lahjan kanssa ole kuin synnin; sillä jos monta ovat sen yhden synnin tähden kuolleet, niin on paljoa enemmin Jumalan armo ja lahja sen yhden ihmisen Jesuksen Kristuksen armossa monen päälle runsaasti tullut."],[5,16,"Ja ei niinkuin (se tuli) yhden kautta, joka syntiä teki, niin myös lahja; sillä tuomio on tosin yhdestä kadotukseen, mutta lahja monesta synnistä vanhurskauteen.","Ja ei niinkuin (se tuli) yhden kautta, joka syntiä teki, niin myös lahja; sillä tuomio on tosin yhdestä kadotukseen, mutta lahja monesta synnistä vanhurskauteen."],[5,17,"Sillä jos kuolema on yhden synnin tähden vallinnut sen yhden kautta, paljoa enemmin ne, jotka saavat armon ja vanhurskauden lahjan yltäkylläisyyden, pitää vallitsemassa elämässä yhden Jesuksen Kristuksen kautta.","Sillä jos kuolema on yhden synnin tähden vallinnut sen yhden kautta, paljoa enemmin ne, jotka saavat armon ja vanhurskauden lahjan yltäkylläisyyden, pitää vallitsemassa elämässä yhden Jesuksen Kristuksen kautta."],[5,18,"Niinkuin siis yhden synnin kautta on kadotus tullut kaikkein ihmisten päälle, niin on myös yhden vanhurskauden kautta elämän vanhurskaus tullut kaikkein ihmisten päälle.","Niinkuin siis yhden synnin kautta on kadotus tullut kaikkein ihmisten päälle, niin on myös yhden vanhurskauden kautta elämän vanhurskaus tullut kaikkein ihmisten päälle."],[5,19,"Sillä niinkuin yhden ihmisen kuulemattomuuden tähden monta ovat syntisiksi tulleet, niin myös monta tulevat yhden kuuliaisuuden tähden vanhurskaiksi.","Sillä niinkuin yhden ihmisen kuulemattomuuden tähden monta ovat syntisiksi tulleet, niin myös monta tulevat yhden kuuliaisuuden tähden vanhurskaiksi."],[5,20,"Mutta laki on myös tähän tullut, että synti suuremmaksi tuttaisiin; mutta kussa synti on suureksi tuttu, siinä on armo ylönpalttiseksi tuttu:","Mutta laki on myös tähän tullut, että synti suuremmaksi tuttaisiin; mutta kussa synti on suureksi tuttu, siinä on armo ylönpalttiseksi tuttu:"],[5,21,"Että niinkuin synti on vallinnut kuolemaan, niin myös armo on vallitseva vanhurskauden kautta ijankaikkiseen elämään, Jesuksen Kristuksen meidän Herramme kautta.","Että niinkuin synti on vallinnut kuolemaan, niin myös armo on vallitseva vanhurskauden kautta ijankaikkiseen elämään, Jesuksen Kristuksen meidän Herramme kautta."],[6,1,"Mitäs siis meidän pitää sanoman? Pitääkö meidän vielä synnissä oleman, että armo suuremmaksi tulis?","Mitäs siis meidän pitää sanoman? Pitääkö meidän vielä synnissä oleman, että armo suuremmaksi tulis?"],[6,2,"Pois se! Me, jotka synnille kuolleet olemme, kuinkas meidän vielä pitäis siinä elämän?","Pois se! Me, jotka synnille kuolleet olemme, kuinkas meidän vielä pitäis siinä elämän?"],[6,3,"Ettekö te tiedä, että me kaikki, jotka olemme Jesuksessa Kristuksessa kastetut, me olemme hänen kuolemaansa kastetut?","Ettekö te tiedä, että me kaikki, jotka olemme Jesuksessa Kristuksessa kastetut, me olemme hänen kuolemaansa kastetut?"],[6,4,"Niin me olemme siis hänen kanssansa haudatut kasteen kautta kuolemaan: että niinkuin Kristus on kuolleista Isän kunnian kautta herätetty, niin pitää meidänkin uudessa elämässä vaeltaman.","Niin me olemme siis hänen kanssansa haudatut kasteen kautta kuolemaan: että niinkuin Kristus on kuolleista Isän kunnian kautta herätetty, niin pitää meidänkin uudessa elämässä vaeltaman."],[6,5,"Sillä jos me ynnä hänen kanssansa olemme istutetut yhdenkaltaiseen kuolemaan, niin me myös tulemme yhdenkaltaiseksi ylösnousemisessa,","Sillä jos me ynnä hänen kanssansa olemme istutetut yhdenkaltaiseen kuolemaan, niin me myös tulemme yhdenkaltaiseksi ylösnousemisessa,"],[6,6,"Tietäen sen, että meidän vanha ihminen on ristiinnaulittu hänen kanssansa, että synnin ruumis pitää turmeltaman, ettemme tästedes syntiä palvelisi.","Tietäen sen, että meidän vanha ihminen on ristiinnaulittu hänen kanssansa, että synnin ruumis pitää turmeltaman, ettemme tästedes syntiä palvelisi."],[6,7,"Sillä se, joka kuollut on, hän on synnistä vanhurskaaksi tehty.","Sillä se, joka kuollut on, hän on synnistä vanhurskaaksi tehty."],[6,8,"Mutta jos me olemme Kristuksen kanssa kuolleet, niin me uskomme, että me saamme myös elää hänen kanssansa,","Mutta jos me olemme Kristuksen kanssa kuolleet, niin me uskomme, että me saamme myös elää hänen kanssansa,"],[6,9,"Ja tiedämme, ettei Kristus, joka kuolleista herätetty on, silleen kuole, eikä kuolema saa tästedes hänen päällensä valtaa.","Ja tiedämme, ettei Kristus, joka kuolleista herätetty on, silleen kuole, eikä kuolema saa tästedes hänen päällensä valtaa."],[6,10,"Sillä sen, kuin hän kuollut on, sen hän synnille kuoli yhden kerran; vaan sen, kuin hän elää, sen hän elää Jumalalle.","Sillä sen, kuin hän kuollut on, sen hän synnille kuoli yhden kerran; vaan sen, kuin hän elää, sen hän elää Jumalalle."],[6,11,"Niin myös te siksi teitänne pitäkäät, että te olette kuolleet synnille, mutta elätte Jumalalle, Jesuksen Kristuksen meidän Herran kautta.","Niin myös te siksi teitänne pitäkäät, että te olette kuolleet synnille, mutta elätte Jumalalle, Jesuksen Kristuksen meidän Herran kautta."],[6,12,"Niin älkäät salliko synnin vallita kuolevaisessa ruumiissanne, niin että te häntä kuulisitte hänen himoissansa.","Niin älkäät salliko synnin vallita kuolevaisessa ruumiissanne, niin että te häntä kuulisitte hänen himoissansa."],[6,13,"Ja älkäät antako teidän jäseniänne vääryyden sota-aseiksi synnille, mutta antakaat teitänne Jumalalle, niinkuin kuolleista eläviksi tulleet, ja teidän jäsenenne Jumalalle vanhurskauden sota-aseiksi.","Ja älkäät antako teidän jäseniänne vääryyden sota-aseiksi synnille, mutta antakaat teitänne Jumalalle, niinkuin kuolleista eläviksi tulleet, ja teidän jäsenenne Jumalalle vanhurskauden sota-aseiksi."],[6,14,"Sillä ei synnin pidä teitä vallitseman, ettette ole lain, vaan armon alla.","Sillä ei synnin pidä teitä vallitseman, ettette ole lain, vaan armon alla."],[6,15,"Kuinkas siis? Pitääkö meidän syntiä tekemän, ettemme lain alla ole, vaan armon? Pois se!","Kuinkas siis? Pitääkö meidän syntiä tekemän, ettemme lain alla ole, vaan armon? Pois se!"],[6,16,"Ettekö te tiedä, että jolle te annatte itsenne palvelioiksi kuulemaan, sen palveliat te olette, jolle te kuuliaiset olette, taikka synnille kuolemaksi eli kuuliaisuudelle vanhurskaudeksi?","Ettekö te tiedä, että jolle te annatte itsenne palvelioiksi kuulemaan, sen palveliat te olette, jolle te kuuliaiset olette, taikka synnille kuolemaksi eli kuuliaisuudelle vanhurskaudeksi?"],[6,17,"Mutta Jumalan olkoon kiitos, että olitte synnin palveliat, mutta nyt te olette sydämestänne kuuliaiset sen opin esikuvalle, johonka te annetut olette.","Mutta Jumalan olkoon kiitos, että olitte synnin palveliat, mutta nyt te olette sydämestänne kuuliaiset sen opin esikuvalle, johonka te annetut olette."],[6,18,"Ja että te olette vapahdetut synnistä, niin te olette vanhurskauden palvelioiksi tulleet.","Ja että te olette vapahdetut synnistä, niin te olette vanhurskauden palvelioiksi tulleet."],[6,19,"Minä puhun ihmisten tavalla, teidän lihanne heikkouden tähden. Sillä niinkuin te ennen annoitte jäsenenne saastaisuutta ja vääryyttä palvelemaan vääryyteen, niin antakaat nyt jäsenenne vanhurskautta palvelemaan pyhitykseen.","Minä puhun ihmisten tavalla, teidän lihanne heikkouden tähden. Sillä niinkuin te ennen annoitte jäsenenne saastaisuutta ja vääryyttä palvelemaan vääryyteen, niin antakaat nyt jäsenenne vanhurskautta palvelemaan pyhitykseen."],[6,20,"Sillä koska te olitte synnin palveliat, niin te olitte vapaat vanhurskaudesta.","Sillä koska te olitte synnin palveliat, niin te olitte vapaat vanhurskaudesta."],[6,21,"Mitä hedelmää siis teidän silloin niistä oli, joita te nyt häpeätte? Sillä niiden loppu on kuolema.","Mitä hedelmää siis teidän silloin niistä oli, joita te nyt häpeätte? Sillä niiden loppu on kuolema."],[6,22,"Mutte että te nyt olette synnistä vapautetut ja Jumalan palvelioiksi tulleet, niin teillä on teidän hedelmänne pyhyyteen, mutta lopuksi ijankaikkinen elämä.","Mutte että te nyt olette synnistä vapautetut ja Jumalan palvelioiksi tulleet, niin teillä on teidän hedelmänne pyhyyteen, mutta lopuksi ijankaikkinen elämä."],[6,23,"Sillä kuolema on synnin palkka, mutta ijankaikkinen elämä on Jumalan lahja Jesuksessa Kristuksessa meidän Herrassamme.","Sillä kuolema on synnin palkka, mutta ijankaikkinen elämä on Jumalan lahja Jesuksessa Kristuksessa meidän Herrassamme."],[7,1,"Ettekö te tiedä, rakkaat veljet, (sillä minä puhun lain taitaville) että laki vallitsee ihmistä niinkauvan kuin hän elää?","Ettekö te tiedä, rakkaat veljet, (sillä minä puhun lain taitaville) että laki vallitsee ihmistä niinkauvan kuin hän elää?"],[7,2,"Sillä vaimo, joka miehen hallussa on, niinkauvan kuin mies elää, on häneen lailla sidottu, mutta jos mies kuolee, niin hän on miehen laista vapaa.","Sillä vaimo, joka miehen hallussa on, niinkauvan kuin mies elää, on häneen lailla sidottu, mutta jos mies kuolee, niin hän on miehen laista vapaa."],[7,3,"Sentähden jos hän toisen miehen kanssa on miehensä eläissä, niin hän huoraksi kutsutaan; mutta jos mies kuolee, niin hän on laista vapaa, ettei hän huoraksi tule, jos hän toisen miehen kanssa on.","Sentähden jos hän toisen miehen kanssa on miehensä eläissä, niin hän huoraksi kutsutaan; mutta jos mies kuolee, niin hän on laista vapaa, ettei hän huoraksi tule, jos hän toisen miehen kanssa on."],[7,4,"Niin olette te myös, minun veljeni, laille kuoletetut Kristuksen ruumiin kautta, että teidän pitää toisen kanssa oleman, joka on noussut kuolleista, että me Jumalalle hedelmän kantaisimme.","Niin olette te myös, minun veljeni, laille kuoletetut Kristuksen ruumiin kautta, että teidän pitää toisen kanssa oleman, joka on noussut kuolleista, että me Jumalalle hedelmän kantaisimme."],[7,5,"Sillä kuin me lihassa olimme, niin ne syntein himot, jotka lain kautta olivat meidän jäsenissämme, vaikuttivat kuolemalle hedelmää saattamaan.","Sillä kuin me lihassa olimme, niin ne syntein himot, jotka lain kautta olivat meidän jäsenissämme, vaikuttivat kuolemalle hedelmää saattamaan."],[7,6,"Mutta nyt me olemme laista vapahdetut ja hänelle kuolleet, jossa me pidettiin kiinni: että me palvelisimme hengen uudistuksessa ja ei puustavin vanhuudessa.","Mutta nyt me olemme laista vapahdetut ja hänelle kuolleet, jossa me pidettiin kiinni: että me palvelisimme hengen uudistuksessa ja ei puustavin vanhuudessa."],[7,7,"Mitäs me siis sanomme? Onko laki synti? Pois se! Mutta en minä muutoin syntiä olisi tuntenut, ellei lain kautta; sillä en minä olisi himoistakaan mitään tiennyt, ellei laki olisi sanonut: ei sinun pidä himoitseman.","Mitäs me siis sanomme? Onko laki synti? Pois se! Mutta en minä muutoin syntiä olisi tuntenut, ellei lain kautta; sillä en minä olisi himoistakaan mitään tiennyt, ellei laki olisi sanonut: ei sinun pidä himoitseman."],[7,8,"Mutta synti otti tilan käskystä ja kehoitti minussa kaikkinaisen himon; sillä ilman lakia oli synti kuollut.","Mutta synti otti tilan käskystä ja kehoitti minussa kaikkinaisen himon; sillä ilman lakia oli synti kuollut."],[7,9,"Mutta minä elin muinen ilman lakia. Kuin siis käsky tuli, niin synti taas virkosi,","Mutta minä elin muinen ilman lakia. Kuin siis käsky tuli, niin synti taas virkosi,"],[7,10,"Ja minä kuolin: ja niin löydettiin, että käsky, joka minulle oli elämäksi, tuli minulle kuolemaksi.","Ja minä kuolin: ja niin löydettiin, että käsky, joka minulle oli elämäksi, tuli minulle kuolemaksi."],[7,11,"Sillä synti, joka otti tilan käskystä, petti minun ja tappoi sen kautta.","Sillä synti, joka otti tilan käskystä, petti minun ja tappoi sen kautta."],[7,12,"Laki on kuitenkin itsestänsä pyhä ja käsky on myös pyhä, oikia ja hyvä.","Laki on kuitenkin itsestänsä pyhä ja käsky on myös pyhä, oikia ja hyvä."],[7,13,"Onko siis se, mikä hyvä on, minulle kuolemaksi tullut? Pois se! Mutta että synti synniksi nähtäisiin, on hän minulle hyvän kautta kuoleman saattanut, että synti ylitse määrän synniksi tulis, käskyn kautta.","Onko siis se, mikä hyvä on, minulle kuolemaksi tullut? Pois se! Mutta että synti synniksi nähtäisiin, on hän minulle hyvän kautta kuoleman saattanut, että synti ylitse määrän synniksi tulis, käskyn kautta."],[7,14,"Sillä me tiedämme, että laki on hengellinen: vaan minä olen lihallinen, synnin alle myyty.","Sillä me tiedämme, että laki on hengellinen: vaan minä olen lihallinen, synnin alle myyty."],[7,15,"Sillä en minä tiedä, mitä minä teen, etten minä tee sitä, mitä minä tahdon, vaan sitä, mitä minä vihaan, teen minä.","Sillä en minä tiedä, mitä minä teen, etten minä tee sitä, mitä minä tahdon, vaan sitä, mitä minä vihaan, teen minä."],[7,16,"Mutta jos minä teen, jota en minä tahdo, niin minä suostun lakiin, että se on hyvä.","Mutta jos minä teen, jota en minä tahdo, niin minä suostun lakiin, että se on hyvä."],[7,17,"Niin en minä sitä enää tee, vaan synti, joka minussa asuu.","Niin en minä sitä enää tee, vaan synti, joka minussa asuu."],[7,18,"Sillä minä tiedän, ettei minussa (se on: minun lihassani) mitään hyvää asu. Sillä tahto minulla on, vaan täyttää hyvää, en minä sitä löydä.","Sillä minä tiedän, ettei minussa (se on: minun lihassani) mitään hyvää asu. Sillä tahto minulla on, vaan täyttää hyvää, en minä sitä löydä."],[7,19,"Sillä hyvää, jota minä tahdon, en minä tee, vaan pahaa, jota en minä tahdo, teen minä.","Sillä hyvää, jota minä tahdon, en minä tee, vaan pahaa, jota en minä tahdo, teen minä."],[7,20,"Mutta jos minä teen, jota en minä tahdo, niin en minä sitä enää tee, vaan synti, joka minussa asuu.","Mutta jos minä teen, jota en minä tahdo, niin en minä sitä enää tee, vaan synti, joka minussa asuu."],[7,21,"Niin minä löydän itsessäni lain, joka tahtoo hyvää tehdä, että minussa pahuus riippuu kiinni.","Niin minä löydän itsessäni lain, joka tahtoo hyvää tehdä, että minussa pahuus riippuu kiinni."],[7,22,"Sillä minulla on halu Jumalan lakiin, sisällisen ihmisen puolesta;","Sillä minulla on halu Jumalan lakiin, sisällisen ihmisen puolesta;"],[7,23,"Mutta minä näen toisen lain minun jäsenissäni, joka sotii minun mieleni lakia vastaan ja ottaa minun vangiksi synnin laissa, joka minun jäsenissäni on.","Mutta minä näen toisen lain minun jäsenissäni, joka sotii minun mieleni lakia vastaan ja ottaa minun vangiksi synnin laissa, joka minun jäsenissäni on."],[7,24,"Minä viheliäinen ihminen: kuka päästää minun tästä kuoleman ruumiista?","Minä viheliäinen ihminen: kuka päästää minun tästä kuoleman ruumiista?"],[7,25,"Minä kiitän Jumalaa Jesuksen Kristuksen meidän Herramme kautta. Niin minä itse palvelen nyt mielellä Jumalan lakia, mutta lihalla synnin lakia.","Minä kiitän Jumalaa Jesuksen Kristuksen meidän Herramme kautta. Niin minä itse palvelen nyt mielellä Jumalan lakia, mutta lihalla synnin lakia."],[8,1,"Niin ei ole nyt yhtään kadotusta niissä, jotka Jesuksessa Kristuksessa ovat, ja ei vaella lihan, vaan hengen jälkeen.","Niin ei ole nyt yhtään kadotusta niissä, jotka Jesuksessa Kristuksessa ovat, ja ei vaella lihan, vaan hengen jälkeen."],[8,2,"Sillä hengen laki, joka eläväksi tekee Kristuksessa Jesuksessa, on minun synnin ja kuoleman laista vapahtanut.","Sillä hengen laki, joka eläväksi tekee Kristuksessa Jesuksessa, on minun synnin ja kuoleman laista vapahtanut."],[8,3,"Sillä se, mikä laille oli mahdotoin, että hän lihan kautta oli heikoksi tullut, sen Jumala teki, ja lähetti Poikansa syntisen lihan hahmossa ja tuomitsi synnin lihassa, synnin kautta:","Sillä se, mikä laille oli mahdotoin, että hän lihan kautta oli heikoksi tullut, sen Jumala teki, ja lähetti Poikansa syntisen lihan hahmossa ja tuomitsi synnin lihassa, synnin kautta:"],[8,4,"Että lain vanhurskaus täytetyksi tulis meissä, jotka emme lihan jälkeen vaella, vaan hengen jälkeen.","Että lain vanhurskaus täytetyksi tulis meissä, jotka emme lihan jälkeen vaella, vaan hengen jälkeen."],[8,5,"Sillä ne, jotka lihan jälkeen ovat, ajattelevat niitä, mitkä lihan ovat; mutta ne, jotka hengen jälkeen ovat, ajattelevat hengellisiä.","Sillä ne, jotka lihan jälkeen ovat, ajattelevat niitä, mitkä lihan ovat; mutta ne, jotka hengen jälkeen ovat, ajattelevat hengellisiä."],[8,6,"Sillä lihan halu on kuolema, ja hengen halu on elämä ja rauha.","Sillä lihan halu on kuolema, ja hengen halu on elämä ja rauha."],[8,7,"Että lihan halu on viha Jumalaa vastaan, ettei se ole Jumalan laille kuuliainen, sillä ei se voikaan.","Että lihan halu on viha Jumalaa vastaan, ettei se ole Jumalan laille kuuliainen, sillä ei se voikaan."],[8,8,"Mutta jotka lihassa ovat, ei ne taida olla Jumalalle otolliset.","Mutta jotka lihassa ovat, ei ne taida olla Jumalalle otolliset."],[8,9,"Mutta ette ole lihassa, vaan hengessä, jos muutoin Jumalan Henki asuu teissä; mutta jolla ei ole Kristuksen Henkeä, ei se ole hänen omansa.","Mutta ette ole lihassa, vaan hengessä, jos muutoin Jumalan Henki asuu teissä; mutta jolla ei ole Kristuksen Henkeä, ei se ole hänen omansa."],[8,10,"Jos siis Kristus teissä on, niin ruumis tosin on kuollut synnin tähden, mutta henki on elämä vanhurskauden tähden.","Jos siis Kristus teissä on, niin ruumis tosin on kuollut synnin tähden, mutta henki on elämä vanhurskauden tähden."],[8,11,"Jos nyt sen Henki, joka Jesuksen kuolleista herätti, asuu teissä, niin myös se, joka Kristuksen kuolleista herätti, on teidän kuolevaiset ruumiinne eläväksi tekevä, sen teissä asuvaisen hengen kautta.","Jos nyt sen Henki, joka Jesuksen kuolleista herätti, asuu teissä, niin myös se, joka Kristuksen kuolleista herätti, on teidän kuolevaiset ruumiinne eläväksi tekevä, sen teissä asuvaisen hengen kautta."],[8,12,"Niin emme nyt ole, rakkaat veljet, velkapäät lihalle, lihan jälkeen elämään.","Niin emme nyt ole, rakkaat veljet, velkapäät lihalle, lihan jälkeen elämään."],[8,13,"Sillä jos te lihan jälkeen elätte, niin teidän pitää kuoleman; mutta jos te lihan työt hengen kautta kuoletatte, niin te saatte elää.","Sillä jos te lihan jälkeen elätte, niin teidän pitää kuoleman; mutta jos te lihan työt hengen kautta kuoletatte, niin te saatte elää."],[8,14,"Sillä kaikki, jotka Jumalan Hengeltä vaikutetaan, ne ovat Jumalan lapset.","Sillä kaikki, jotka Jumalan Hengeltä vaikutetaan, ne ovat Jumalan lapset."],[8,15,"Sillä ette ole saaneet orjuuden henkeä, että teidän vielä pitäis pelkäämän, mutta te olette saaneet valittuin lasten hengen, jossa me huudamme: Abba, rakas Isä.","Sillä ette ole saaneet orjuuden henkeä, että teidän vielä pitäis pelkäämän, mutta te olette saaneet valittuin lasten hengen, jossa me huudamme: Abba, rakas Isä."],[8,16,"Se Henki todistaa meidän henkemme kanssa, että me olemme Jumalan lapset.","Se Henki todistaa meidän henkemme kanssa, että me olemme Jumalan lapset."],[8,17,"Jos me olemme lapset, niin me olemme myös perilliset, nimittäin Jumalan perilliset ja Kristuksen kanssaperilliset: jos me muutoin ynnä kärsimme, että me ynnä hänen kanssansa kunniaan tulisimme.","Jos me olemme lapset, niin me olemme myös perilliset, nimittäin Jumalan perilliset ja Kristuksen kanssaperilliset: jos me muutoin ynnä kärsimme, että me ynnä hänen kanssansa kunniaan tulisimme."],[8,18,"Sillä siksi minä sen pidän, ettei tämän nykyisen ajan vaivat ole sen kunnian vertaa, joka meille ilmoitetaan.","Sillä siksi minä sen pidän, ettei tämän nykyisen ajan vaivat ole sen kunnian vertaa, joka meille ilmoitetaan."],[8,19,"Sillä ikävä luontokappaleen ikävöitsemys odottaa Jumalan lasten ilmoitusta,","Sillä ikävä luontokappaleen ikävöitsemys odottaa Jumalan lasten ilmoitusta,"],[8,20,"Että luontokappale on turmeluksen alle annettu, ei mielellänsä, vaan sentähden, joka ne alle antanut on,","Että luontokappale on turmeluksen alle annettu, ei mielellänsä, vaan sentähden, joka ne alle antanut on,"],[8,21,"Toivossa, että myös itse luontokappale pitää turmeluksen orjuudesta vapaaksi tuleman, Jumalan lasten kunnian vapauteen.","Toivossa, että myös itse luontokappale pitää turmeluksen orjuudesta vapaaksi tuleman, Jumalan lasten kunnian vapauteen."],[8,22,"Sillä me tiedämme, että jokainen luontokappale huokaa ja ahdistetaan aina tähän asti meidän kanssamme.","Sillä me tiedämme, että jokainen luontokappale huokaa ja ahdistetaan aina tähän asti meidän kanssamme."],[8,23,"Mutta ei ainoastaan ne, vaan myös itse me, joilla hengen uutiset ovat, huokaamme itsellämme, odottain sitä lapseksi ottamista, meidän ruumiimme lunastusta.","Mutta ei ainoastaan ne, vaan myös itse me, joilla hengen uutiset ovat, huokaamme itsellämme, odottain sitä lapseksi ottamista, meidän ruumiimme lunastusta."],[8,24,"Sillä me olemme toivossa vapahdetut. Mutta jos toivo näkyy, niin ei se ole toivo; sillä kuinka joku taitaa toivoa jota hän näkee?","Sillä me olemme toivossa vapahdetut. Mutta jos toivo näkyy, niin ei se ole toivo; sillä kuinka joku taitaa toivoa jota hän näkee?"],[8,25,"Mutta jos me sitä toivomme, jota emme näe, niin me odotamme sitä kärsivällisyydessä.","Mutta jos me sitä toivomme, jota emme näe, niin me odotamme sitä kärsivällisyydessä."],[8,26,"Mutta niin myös Henki auttaa meidän heikkouttamme; sillä emmepä me tiedä mitään rukoilla niinkuin tulis, vaan Henki rukoilee meidän edestämme sanomattomilla huokauksilla.","Mutta niin myös Henki auttaa meidän heikkouttamme; sillä emmepä me tiedä mitään rukoilla niinkuin tulis, vaan Henki rukoilee meidän edestämme sanomattomilla huokauksilla."],[8,27,"Mutta joka sydämet tutkii, hän tietää, mitä Hengen mielessä on; sillä hän rukoilee pyhäin edestä Jumalan tahdon jälkeen.","Mutta joka sydämet tutkii, hän tietää, mitä Hengen mielessä on; sillä hän rukoilee pyhäin edestä Jumalan tahdon jälkeen."],[8,28,"Mutta me tiedämme niille, jotka Jumalaa rakastavat, kaikki kappaleet ynnä parhaaksi kääntyvän, niille, jotka aivoituksen jälkeen kutsutut ovat.","Mutta me tiedämme niille, jotka Jumalaa rakastavat, kaikki kappaleet ynnä parhaaksi kääntyvän, niille, jotka aivoituksen jälkeen kutsutut ovat."],[8,29,"Sillä jotka hän on katsonut edes, ne hän on Poikansa kuvan kaltaiseksi säätänyt, että hän olis esikoinen monen veljen keskellä.","Sillä jotka hän on katsonut edes, ne hän on Poikansa kuvan kaltaiseksi säätänyt, että hän olis esikoinen monen veljen keskellä."],[8,30,"Mutta jotka hän on säätänyt, ne hän on myös kutsunut, ja jotka hän kutsunut on, ne hän on myös vanhurskaiksi tehnyt, ja jotka hän vanhurskaiksi teki, ne hän on myös kunniallisiksi tehnyt.","Mutta jotka hän on säätänyt, ne hän on myös kutsunut, ja jotka hän kutsunut on, ne hän on myös vanhurskaiksi tehnyt, ja jotka hän vanhurskaiksi teki, ne hän on myös kunniallisiksi tehnyt."],[8,31,"Mitäs me siis näihin sanomme? Jos Jumala on meidän edestämme, kuka voi meitä vastaan olla?","Mitäs me siis näihin sanomme? Jos Jumala on meidän edestämme, kuka voi meitä vastaan olla?"],[8,32,"Joka ei omaakaan Poikaansa armahtanut, vaan antoi hänen kaikkein meidän edestämme, eikös hän myös lahjoita meille kaikkia hänen kanssansa?","Joka ei omaakaan Poikaansa armahtanut, vaan antoi hänen kaikkein meidän edestämme, eikös hän myös lahjoita meille kaikkia hänen kanssansa?"],[8,33,"Kuka tahtoo Jumalan valittuin päälle kantaa? Jumala on, joka tekee vanhurskaaksi.","Kuka tahtoo Jumalan valittuin päälle kantaa? Jumala on, joka tekee vanhurskaaksi."],[8,34,"Kuka on, joka tahtoo kadottaa? Kristus on kuollut. Ja, hän on myös herätetty ylös, on myös Jumalan oikialla kädellä, joka myös rukoilee meidän edestämme.","Kuka on, joka tahtoo kadottaa? Kristus on kuollut. Ja, hän on myös herätetty ylös, on myös Jumalan oikialla kädellä, joka myös rukoilee meidän edestämme."],[8,35,"Kuka pitää meitä Kristuksen rakkaudesta eroittaman? vaivako, eli ahdistus, eli vaino, eli nälkä, eli alastomuus, eli hätä, eli miekka?","Kuka pitää meitä Kristuksen rakkaudesta eroittaman? vaivako, eli ahdistus, eli vaino, eli nälkä, eli alastomuus, eli hätä, eli miekka?"],[8,36,"Niinkuin kirjoitettu on: sinun tähtes me kuoletetaan yli päivää: me pidetään niinkuin teurastettavat lampaat.","Niinkuin kirjoitettu on: sinun tähtes me kuoletetaan yli päivää: me pidetään niinkuin teurastettavat lampaat."],[8,37,"Mutta niissä kaikissa me voitamme hänen kauttansa, joka meitä on rakastanut.","Mutta niissä kaikissa me voitamme hänen kauttansa, joka meitä on rakastanut."],[8,38,"Sillä minä olen vahva siitä, ettei kuolema, eikä elämä, eikä enkelit, eikä esivallat, eikä väkevyydet, eikä nykyiset, eikä tulevaiset,","Sillä minä olen vahva siitä, ettei kuolema, eikä elämä, eikä enkelit, eikä esivallat, eikä väkevyydet, eikä nykyiset, eikä tulevaiset,"],[8,39,"Eikä korkeus, eikä syvyys, eli joku muu luontokappale taida meitä Jumalan rakkaudesta eroittaa, joka on Jesuksessa Kristuksessa, meidän Herrassamme.","Eikä korkeus, eikä syvyys, eli joku muu luontokappale taida meitä Jumalan rakkaudesta eroittaa, joka on Jesuksessa Kristuksessa, meidän Herrassamme."],[9,1,"Minä sanon totuuden Kristuksessa ja en valehtele, (niinkuin minun omatuntoni minun kanssani Pyhässä Hengessä todistaa,)","Minä sanon totuuden Kristuksessa ja en valehtele, (niinkuin minun omatuntoni minun kanssani Pyhässä Hengessä todistaa,)"],[9,2,"Että minulla on suuri murhe ja alinomainen kipu sydämessäni.","Että minulla on suuri murhe ja alinomainen kipu sydämessäni."],[9,3,"Minä olen pyytänyt kirottuna olla Kristukselta minun veljieni tähden, jotka lihan puolesta minun lankoni ovat,","Minä olen pyytänyt kirottuna olla Kristukselta minun veljieni tähden, jotka lihan puolesta minun lankoni ovat,"],[9,4,"Jotka ovat Israelilaiset, joiden on lasten oikeus ja kunnia, ja liitot ja laki, ja jumalanpalvelus ja lupaukset,","Jotka ovat Israelilaiset, joiden on lasten oikeus ja kunnia, ja liitot ja laki, ja jumalanpalvelus ja lupaukset,"],[9,5,"Joiden myös isät ovat, joista Kristus lihan puolesta syntynyt on, joka on Jumala ylitse kaikkein ylistetty ijankaikkisesti, amen!","Joiden myös isät ovat, joista Kristus lihan puolesta syntynyt on, joka on Jumala ylitse kaikkein ylistetty ijankaikkisesti, amen!"],[9,6,"Mutta ei niin, että Jumalan sana on hukkunut; sillä ei ne ole kaikki Israelilaiset, jotka Israelista ovat.","Mutta ei niin, että Jumalan sana on hukkunut; sillä ei ne ole kaikki Israelilaiset, jotka Israelista ovat."],[9,7,"Ei myös ne ole kaikki lapset, jotka Abrahamin siemen ovat; vaan Isakissa pitää sinulle siemen kutsuttaman.","Ei myös ne ole kaikki lapset, jotka Abrahamin siemen ovat; vaan Isakissa pitää sinulle siemen kutsuttaman."],[9,8,"Se on: ei ne ole Jumalan lapset, jotka lihan puolesta lapset ovat; mutta ne, jotka lupauksen lapset ovat, ne siemeneksi luetaan.","Se on: ei ne ole Jumalan lapset, jotka lihan puolesta lapset ovat; mutta ne, jotka lupauksen lapset ovat, ne siemeneksi luetaan."],[9,9,"Sillä tämä on lupauksen sana: tällä ajalla minä tulen ja Saaralla pitää poika oleman.","Sillä tämä on lupauksen sana: tällä ajalla minä tulen ja Saaralla pitää poika oleman."],[9,10,"Mutta ei se ainoastaan, mutta myös Rebekka siitti yhdestä Isaakista meidän isästämme.","Mutta ei se ainoastaan, mutta myös Rebekka siitti yhdestä Isaakista meidän isästämme."],[9,11,"Sillä ennen kuin lapset syntyivätkään ja kuin ei he vielä hyvää eikä pahaa tehneet olleet, että Jumalan aivoitus pitäis valitsemisen jälkeen seisovainen oleman, ei töiden tähden, vaan kutsujan armosta,","Sillä ennen kuin lapset syntyivätkään ja kuin ei he vielä hyvää eikä pahaa tehneet olleet, että Jumalan aivoitus pitäis valitsemisen jälkeen seisovainen oleman, ei töiden tähden, vaan kutsujan armosta,"],[9,12,"Sanottiin hänelle: suuremman pitää vähempää palveleman.","Sanottiin hänelle: suuremman pitää vähempää palveleman."],[9,13,"Niinkuin kirjoitettu on: Jakobia minä rakastin, mutta Esauta vihasin.","Niinkuin kirjoitettu on: Jakobia minä rakastin, mutta Esauta vihasin."],[9,14,"Mitäs me siis sanomme? Onko Jumalan tykönä vääryyttä? Pois se!","Mitäs me siis sanomme? Onko Jumalan tykönä vääryyttä? Pois se!"],[9,15,"Sillä hän sanoo Mosekselle: jota minä armahdan, sitä minä tahdon armahtaa, ja tahdon olla laupias, jolle minä laupias olen.","Sillä hän sanoo Mosekselle: jota minä armahdan, sitä minä tahdon armahtaa, ja tahdon olla laupias, jolle minä laupias olen."],[9,16,"Niin ei se nyt ole sen, joka tahtoo, eikä sen, joka juoksee, vaan sen, joka armahtaa, nimittäin Jumalan.","Niin ei se nyt ole sen, joka tahtoo, eikä sen, joka juoksee, vaan sen, joka armahtaa, nimittäin Jumalan."],[9,17,"Sillä Raamattu sanoo Pharaolle: juuri sentähden olen minä sinun herättänyt, osoittaakseni minun voimani sinussa, että minun nimeni kaikessa maassa julistettaisiin.","Sillä Raamattu sanoo Pharaolle: juuri sentähden olen minä sinun herättänyt, osoittaakseni minun voimani sinussa, että minun nimeni kaikessa maassa julistettaisiin."],[9,18,"Niin hän siis armahtaa, ketä hän tahtoo, ja paaduttaa, kenenkä hän tahtoo.","Niin hän siis armahtaa, ketä hän tahtoo, ja paaduttaa, kenenkä hän tahtoo."],[9,19,"Niin sinä sanot minulle: mitä hän siis nuhtelee? sillä kuka taitaa hänen tahtoansa vastaan olla?","Niin sinä sanot minulle: mitä hän siis nuhtelee? sillä kuka taitaa hänen tahtoansa vastaan olla?"],[9,20,"Ja tosin, oi ihminen, kuka sinä olet, joka Jumalaa vastaan riitelet? Sanooko työ tekiällensä: miksis minut tainkaltaiseksi tehnyt olet?","Ja tosin, oi ihminen, kuka sinä olet, joka Jumalaa vastaan riitelet? Sanooko työ tekiällensä: miksis minut tainkaltaiseksi tehnyt olet?"],[9,21,"Eli eikö savenvalajalla ole saven päälle valtaa, yhdestä kappaleesta tehdä yhtä astiaa kunnialliseksi ja toista huonoksi?","Eli eikö savenvalajalla ole saven päälle valtaa, yhdestä kappaleesta tehdä yhtä astiaa kunnialliseksi ja toista huonoksi?"],[9,22,"Sentähden, jos Jumala tahtoo vihansa osoittaa ja voimansa ilmoittaa, on hän suurella kärsivällisyydellä kärsinyt vihansa astioita, jotka ovat kadotukseen valmistetut.","Sentähden, jos Jumala tahtoo vihansa osoittaa ja voimansa ilmoittaa, on hän suurella kärsivällisyydellä kärsinyt vihansa astioita, jotka ovat kadotukseen valmistetut."],[9,23,"Ja että hän tiettäväksi tekis kunniansa rikkauden laupiutensa astioille, jotka hän kunniaan on valmistanut,","Ja että hän tiettäväksi tekis kunniansa rikkauden laupiutensa astioille, jotka hän kunniaan on valmistanut,"],[9,24,"Jotka hän myös kutsunut on, nimittäin meitä, ei ainoasti Juudalaisista, vaan myös pakanoista,","Jotka hän myös kutsunut on, nimittäin meitä, ei ainoasti Juudalaisista, vaan myös pakanoista,"],[9,25,"Niinkuin hän myös Hosean kautta sanoo: minä tahdon kutsua sen minun kansakseni, joka ei ollut minun kansani, ja minun rakkaakseni, joka ei minun rakkaani ollut.","Niinkuin hän myös Hosean kautta sanoo: minä tahdon kutsua sen minun kansakseni, joka ei ollut minun kansani, ja minun rakkaakseni, joka ei minun rakkaani ollut."],[9,26,"Ja pitää tapahtuman, että siinä paikassa, missä heille sanottiin: ette ole minun kansani, siellä pitää heitä elävän Jumalan lapsiksi kutsuttaman.","Ja pitää tapahtuman, että siinä paikassa, missä heille sanottiin: ette ole minun kansani, siellä pitää heitä elävän Jumalan lapsiksi kutsuttaman."],[9,27,"Mutta Jesaias huutaa Israelin edestä: jos Israelin lasten luku olis niinkuin santa meressä, niin kuitenkin tähteet autuaaksi tulevat.","Mutta Jesaias huutaa Israelin edestä: jos Israelin lasten luku olis niinkuin santa meressä, niin kuitenkin tähteet autuaaksi tulevat."],[9,28,"Sillä kuluttamus ja lyhentämys pitää tapahtuman vanhurskaudeksi, että Herra tekee hävityksen maan päällä,","Sillä kuluttamus ja lyhentämys pitää tapahtuman vanhurskaudeksi, että Herra tekee hävityksen maan päällä,"],[9,29,"Ja niinkuin Jesaias ennen sanoi: ellei Herra Zebaot olisi meille siementä jättänyt, niin me olisimme olleet kuin Sodoma ja senkaltaiset kuin Gomorra.","Ja niinkuin Jesaias ennen sanoi: ellei Herra Zebaot olisi meille siementä jättänyt, niin me olisimme olleet kuin Sodoma ja senkaltaiset kuin Gomorra."],[9,30,"Mitäs me siis sanomme? (Me sanomme:) pakanat, jotka ei ole vanhurskautta etsineet, ovat saaneet vanhurskauden, mutta sen vanhurskauden, joka uskosta on:","Mitäs me siis sanomme? (Me sanomme:) pakanat, jotka ei ole vanhurskautta etsineet, ovat saaneet vanhurskauden, mutta sen vanhurskauden, joka uskosta on:"],[9,31,"Mutta Israel, joka vanhurskauden lakia on etsinyt, ei ole vanhurskauden lakia saanut.","Mutta Israel, joka vanhurskauden lakia on etsinyt, ei ole vanhurskauden lakia saanut."],[9,32,"Minkätähden? Ettei he sitä uskosta, mutta niinkuin lain töistä etsivät. Sillä he ovat loukanneet itsensä loukkauskiveen.","Minkätähden? Ettei he sitä uskosta, mutta niinkuin lain töistä etsivät. Sillä he ovat loukanneet itsensä loukkauskiveen."],[9,33,"Niinkuin kirjoitettu on: katso, minä panen Zioniin loukkauskiven ja pahennuksen kallion, ja jokainen, joka hänen päällensä uskoo, ei pidä häpiään tuleman.","Niinkuin kirjoitettu on: katso, minä panen Zioniin loukkauskiven ja pahennuksen kallion, ja jokainen, joka hänen päällensä uskoo, ei pidä häpiään tuleman."],[10,1,"Veljet, minun sydämeni halu ja rukous on Jumalan tykö Israelin edestä, että he autuaaksi tulisivat.","Veljet, minun sydämeni halu ja rukous on Jumalan tykö Israelin edestä, että he autuaaksi tulisivat."],[10,2,"Sillä minä annan heille todistuksen, että heillä on kiivaus Jumalan puoleen, mutta ei taidon jälkeen.","Sillä minä annan heille todistuksen, että heillä on kiivaus Jumalan puoleen, mutta ei taidon jälkeen."],[10,3,"Sillä ei he ymmärrä Jumalan vanhurskautta, vaan pyytävät omaa vanhurskauttansa vahvistaa, eikä ole Jumalan vanhurskaudelle kuuliaiset:","Sillä ei he ymmärrä Jumalan vanhurskautta, vaan pyytävät omaa vanhurskauttansa vahvistaa, eikä ole Jumalan vanhurskaudelle kuuliaiset:"],[10,4,"Sillä Kristus on lain loppu, jokaiselle uskovaiselle vanhurskaudeksi.","Sillä Kristus on lain loppu, jokaiselle uskovaiselle vanhurskaudeksi."],[10,5,"Sillä Moses kirjoittaa siitä vanhurskaudesta, joka laista on, että kuka ihminen ne tekee, hänen pitää niissä elämän.","Sillä Moses kirjoittaa siitä vanhurskaudesta, joka laista on, että kuka ihminen ne tekee, hänen pitää niissä elämän."],[10,6,"Mutta se vanhurskaus, joka uskosta on, sanoo näin: älä sano sydämessäs: kuka tahtoo astua ylös taivaasen? se on Kristusta tänne tuoda alas.","Mutta se vanhurskaus, joka uskosta on, sanoo näin: älä sano sydämessäs: kuka tahtoo astua ylös taivaasen? se on Kristusta tänne tuoda alas."],[10,7,"Eli kuka tahtoo astua alas syvyyteen: se on: Kristusta kuolleista jälleen tuoda?","Eli kuka tahtoo astua alas syvyyteen: se on: Kristusta kuolleista jälleen tuoda?"],[10,8,"Vaan mitä hän sanoo? Se sana on juuri sinun tykönäs, nimittäin sinun suussas ja sydämessäs. Tämä on se sana uskosta, jota me saarnaamme.","Vaan mitä hän sanoo? Se sana on juuri sinun tykönäs, nimittäin sinun suussas ja sydämessäs. Tämä on se sana uskosta, jota me saarnaamme."],[10,9,"Sillä, jos sinä suullas tunnustat Herran Jesuksen ja uskot sydämessäs, että Jumala on hänet kuolleista herättänyt, niin sinä tulet autuaaksi;","Sillä, jos sinä suullas tunnustat Herran Jesuksen ja uskot sydämessäs, että Jumala on hänet kuolleista herättänyt, niin sinä tulet autuaaksi;"],[10,10,"Sillä sydämen uskolla me vanhurskaaksi tulemme, ja suun tunnustuksella me autuaaksi tulemme.","Sillä sydämen uskolla me vanhurskaaksi tulemme, ja suun tunnustuksella me autuaaksi tulemme."],[10,11,"Sillä Raamattu sanoo: jokainen, joka uskoo hänen päällensä, ei pidä häpiään tuleman.","Sillä Raamattu sanoo: jokainen, joka uskoo hänen päällensä, ei pidä häpiään tuleman."],[10,12,"Ei ole yhtään eroitusta Juudalaisen ja Grekiläisen välillä; sillä yksi on kaikkein Herra, rikas kaikkein kohtaan, jotka häntä rukoilevat.","Ei ole yhtään eroitusta Juudalaisen ja Grekiläisen välillä; sillä yksi on kaikkein Herra, rikas kaikkein kohtaan, jotka häntä rukoilevat."],[10,13,"Sillä jokainen, joka Herran nimeä avuksensa huutaa, tulee autuaaksi.","Sillä jokainen, joka Herran nimeä avuksensa huutaa, tulee autuaaksi."],[10,14,"Mutta kuinka he sitä avuksensa huutavat, jonka päälle ei he uskoneet? Ja kuinka he sen uskovat, josta ei he ole kuulleet? Mutta kuinka he kuulevat ilman saarnaajaa?","Mutta kuinka he sitä avuksensa huutavat, jonka päälle ei he uskoneet? Ja kuinka he sen uskovat, josta ei he ole kuulleet? Mutta kuinka he kuulevat ilman saarnaajaa?"],[10,15,"Ja kuinka he saarnaavat, ellei heitä lähetetä? Niinkuin kirjoitettu on: oi kuinka suloiset ovat niiden jalat, jotka rauhaa julistavat, niiden jotka hyvää julistavat.","Ja kuinka he saarnaavat, ellei heitä lähetetä? Niinkuin kirjoitettu on: oi kuinka suloiset ovat niiden jalat, jotka rauhaa julistavat, niiden jotka hyvää julistavat."],[10,16,"Mutta ei he ole kaikki evankeliumille kuuliaiset; sillä Jesaias sanoo: Herra, kuka uskoo meidän saarnamme?","Mutta ei he ole kaikki evankeliumille kuuliaiset; sillä Jesaias sanoo: Herra, kuka uskoo meidän saarnamme?"],[10,17,"Niin tulee siis usko kuulosta, mutta kuulo Jumalan sanan kautta.","Niin tulee siis usko kuulosta, mutta kuulo Jumalan sanan kautta."],[10,18,"Mutta minä sanon: eikö he sitä ole kuulleet? Heidän äänensä tosin on lähtenyt kaikkeen maailmaan ja heidän sanansa maailman ääriin.","Mutta minä sanon: eikö he sitä ole kuulleet? Heidän äänensä tosin on lähtenyt kaikkeen maailmaan ja heidän sanansa maailman ääriin."],[10,19,"Vaan minä sanon: eikös Israel tietänyt? Ensimäinen Moses sanoo: minä tahdon teitä yllyttää kateuteen sen kansan kautta, joka ei minun kansani ole, ja tyhmän kansan kautta tahdon minä teitä härsytellä.","Vaan minä sanon: eikös Israel tietänyt? Ensimäinen Moses sanoo: minä tahdon teitä yllyttää kateuteen sen kansan kautta, joka ei minun kansani ole, ja tyhmän kansan kautta tahdon minä teitä härsytellä."],[10,20,"Mutta Jesaias on rohkia ja sanoo: minä olen niiltä löydetty, jotka ei minua etsineet, ja olen niille ilmaantunut, jotka ei minua kysyneet.","Mutta Jesaias on rohkia ja sanoo: minä olen niiltä löydetty, jotka ei minua etsineet, ja olen niille ilmaantunut, jotka ei minua kysyneet."],[10,21,"Mutta Israelille hän sanoo: koko päivän olen minä käteni ojentanut tottelemattomalle ja vastahakoiselle kansalle.","Mutta Israelille hän sanoo: koko päivän olen minä käteni ojentanut tottelemattomalle ja vastahakoiselle kansalle."],[11,1,"Niin minä siis sanon: onkos Jumala kansansa hyljännyt? Pois se! sillä minä olen myös Israelilainen, Abrahamin siemenestä, Benjaminin suvusta.","Niin minä siis sanon: onkos Jumala kansansa hyljännyt? Pois se! sillä minä olen myös Israelilainen, Abrahamin siemenestä, Benjaminin suvusta."],[11,2,"Ei Jumala ole kansaansa hyljännyt, jonka hän ennen on tuntenut. Ettekö te tiedä, mitä Raamattu Eliaasta sanoo? kuinka hän rukoilee Jumalaa Israelia vastaan, sanoen:","Ei Jumala ole kansaansa hyljännyt, jonka hän ennen on tuntenut. Ettekö te tiedä, mitä Raamattu Eliaasta sanoo? kuinka hän rukoilee Jumalaa Israelia vastaan, sanoen:"],[11,3,"Herra, he ovat tappaneet sinun prophetas ja sinun alttaris kukistaneet, ja minä yksinäni jäin, ja he etsivät minunkin henkeäni.","Herra, he ovat tappaneet sinun prophetas ja sinun alttaris kukistaneet, ja minä yksinäni jäin, ja he etsivät minunkin henkeäni."],[11,4,"Mutta mitä Jumalan vastaus sanoo hänelle? Minä olen itselleni jättänyt seitsemäntuhatta miestä, jotka ei ole Baalille polviansa taivuttaneet.","Mutta mitä Jumalan vastaus sanoo hänelle? Minä olen itselleni jättänyt seitsemäntuhatta miestä, jotka ei ole Baalille polviansa taivuttaneet."],[11,5,"Niin ovat jääneet tälläkin ajalla armon valitsemisen jälkeen.","Niin ovat jääneet tälläkin ajalla armon valitsemisen jälkeen."],[11,6,"Mutta jos se armosta on, niin ei se ole enään töistä, sillä ei armo muutoin armo olisikaan. Mutta jos se on töistä, niin ei se silleen armo ole; muutoin ei työ enään ole työ.","Mutta jos se armosta on, niin ei se ole enään töistä, sillä ei armo muutoin armo olisikaan. Mutta jos se on töistä, niin ei se silleen armo ole; muutoin ei työ enään ole työ."],[11,7,"Kuinkas siis? Jota Israel etsii, sitä ei hän ole saanut; mutta valitut sen ovat saaneet ja ne muut ovat paatuneet,","Kuinkas siis? Jota Israel etsii, sitä ei hän ole saanut; mutta valitut sen ovat saaneet ja ne muut ovat paatuneet,"],[11,8,"(Niinkuin kirjoitettu on: Jumala on antanut heille uppiniskaisen hengen, silmät, ettei he näkisi, ja korvat, ettei he kuulisi) tähän päivään asti.","(Niinkuin kirjoitettu on: Jumala on antanut heille uppiniskaisen hengen, silmät, ettei he näkisi, ja korvat, ettei he kuulisi) tähän päivään asti."],[11,9,"Ja David sanoo: heidän pöytänsä tulkoon heille paulaksi, ja satimeksi, ja pahennukseksi, ja kostoksi.","Ja David sanoo: heidän pöytänsä tulkoon heille paulaksi, ja satimeksi, ja pahennukseksi, ja kostoksi."],[11,10,"Heidän silmänsä soetkoon, ettei he näkisi, ja taita aina heidän selkänsä!","Heidän silmänsä soetkoon, ettei he näkisi, ja taita aina heidän selkänsä!"],[11,11,"Niin minä siis sanon: ovatko he sentähden itsensä loukanneet, että heidän piti lankeeman? Pois se! vaan heidän lankeemisestansa tapahtui pakanoille autuus, että hän sais heitä kiivaaksi heidän tähtensä.","Niin minä siis sanon: ovatko he sentähden itsensä loukanneet, että heidän piti lankeeman? Pois se! vaan heidän lankeemisestansa tapahtui pakanoille autuus, että hän sais heitä kiivaaksi heidän tähtensä."],[11,12,"Mutta jos heidän lankeemisensa on maailman rikkaus ja heidän vähennöksensä on pakanain rikkaus; kuinka paljoa enemmin heidän täydellisyytensä?","Mutta jos heidän lankeemisensa on maailman rikkaus ja heidän vähennöksensä on pakanain rikkaus; kuinka paljoa enemmin heidän täydellisyytensä?"],[11,13,"Sillä teille pakanoille minä puhun: että minä pakanain apostoli olen, ylistän minä minun virkaani.","Sillä teille pakanoille minä puhun: että minä pakanain apostoli olen, ylistän minä minun virkaani."],[11,14,"Jos minä taitaisin jollakin tavalla niitä, jotka minun lihani ovat, kiivaaksi saada ja muutamatkin heistä autuaaksi saattaa.","Jos minä taitaisin jollakin tavalla niitä, jotka minun lihani ovat, kiivaaksi saada ja muutamatkin heistä autuaaksi saattaa."],[11,15,"Sillä jos heidän hylkäämisensä on maailman sovinto, mitäs heidän korjaamisensa muuta on kuin elämä kuolleista?","Sillä jos heidän hylkäämisensä on maailman sovinto, mitäs heidän korjaamisensa muuta on kuin elämä kuolleista?"],[11,16,"Sillä jos alku on pyhä, niin on myös koko taikina, ja jos juuri on pyhä, niin ovat myös oksat.","Sillä jos alku on pyhä, niin on myös koko taikina, ja jos juuri on pyhä, niin ovat myös oksat."],[11,17,"Mutta jos muutamat oksista ovat murtuneet, ja sinä, joka metsä-öljypuu olit, olet niihin istutettu, ja olet öljypuun juuresta ja lihavuudesta osalliseksi tullut,","Mutta jos muutamat oksista ovat murtuneet, ja sinä, joka metsä-öljypuu olit, olet niihin istutettu, ja olet öljypuun juuresta ja lihavuudesta osalliseksi tullut,"],[11,18,"Niin älä ylpeile oksia vastaan; mutta jos sinä heitä vastaan ylpeilet, niin tiedä, ettet sinä juurta kanna, vaan juuri kantaa sinua.","Niin älä ylpeile oksia vastaan; mutta jos sinä heitä vastaan ylpeilet, niin tiedä, ettet sinä juurta kanna, vaan juuri kantaa sinua."],[11,19,"Niin sanot; oksat ovat murtuneet, että minun piti siihen jälleen istutettaman.","Niin sanot; oksat ovat murtuneet, että minun piti siihen jälleen istutettaman."],[11,20,"Oikein: he ovat murtuneet epäuskonsa tähden, mutta sinä pysyt uskon kautta: älä ole röyhkeä, vaan pelkää.","Oikein: he ovat murtuneet epäuskonsa tähden, mutta sinä pysyt uskon kautta: älä ole röyhkeä, vaan pelkää."],[11,21,"Sillä jos ei Jumala luonnollisia oksia armahtanut, katso, ei hän sinuakaan armahda.","Sillä jos ei Jumala luonnollisia oksia armahtanut, katso, ei hän sinuakaan armahda."],[11,22,"Sentähden katso tässä Jumalan hyvyyttä ja ankaruutta: ankaruutta niissä, jotka lankesivat, mutta hyvyyttä itse sinussas, jos sinä ainoastaan hyvyydessä pysyt; muutoin sinäkin leikataan pois.","Sentähden katso tässä Jumalan hyvyyttä ja ankaruutta: ankaruutta niissä, jotka lankesivat, mutta hyvyyttä itse sinussas, jos sinä ainoastaan hyvyydessä pysyt; muutoin sinäkin leikataan pois."],[11,23,"Ja ne jälleen istutetaan, ellei he epäuskossansa pysy; sillä Jumala on voimallinen heitä jälleen istuttamaan.","Ja ne jälleen istutetaan, ellei he epäuskossansa pysy; sillä Jumala on voimallinen heitä jälleen istuttamaan."],[11,24,"Sillä jos sinä olet luonnollisesta metsä-öljypuusta karsittu, ja olet vastoin luontoa hyvään öljypuuhun istutettu, kuinka paljon enemmin ne, jotka luonnolliset ovat, omaan öljypuuhunsa istutetaan?","Sillä jos sinä olet luonnollisesta metsä-öljypuusta karsittu, ja olet vastoin luontoa hyvään öljypuuhun istutettu, kuinka paljon enemmin ne, jotka luonnolliset ovat, omaan öljypuuhunsa istutetaan?"],[11,25,"Sillä en minä tahdo salata teiltä, rakkaat veljet, tätä salaisuutta, (ettette itsellänne ylpeilisi,) että paatumus on puolittain Israelille tullut, siihenasti kuin pakanain täydellisyys tulis.","Sillä en minä tahdo salata teiltä, rakkaat veljet, tätä salaisuutta, (ettette itsellänne ylpeilisi,) että paatumus on puolittain Israelille tullut, siihenasti kuin pakanain täydellisyys tulis."],[11,26,"Ja niin kaikki Israel pitää autuaaksi tuleman, niinkuin kirjoitettu on: se tulee Zionista, joka päästää ja jumalattoman menon Jakobista kääntää pois.","Ja niin kaikki Israel pitää autuaaksi tuleman, niinkuin kirjoitettu on: se tulee Zionista, joka päästää ja jumalattoman menon Jakobista kääntää pois."],[11,27,"Ja tämä on minun liittoni heidän kanssansa, kuin minä otan pois heidän syntinsä.","Ja tämä on minun liittoni heidän kanssansa, kuin minä otan pois heidän syntinsä."],[11,28,"Evankeliumin puolesta tosin ovat he viholliset teidän tähtenne; mutta valitsemisen puolesta rakastetaan heitä isäin tähden.","Evankeliumin puolesta tosin ovat he viholliset teidän tähtenne; mutta valitsemisen puolesta rakastetaan heitä isäin tähden."],[11,29,"Sillä ei Jumala lahjojansa ja kutsumistansa kadu.","Sillä ei Jumala lahjojansa ja kutsumistansa kadu."],[11,30,"Sillä niinkuin ette tekään muinen Jumalan päälle uskoneet, mutta olette nyt laupiuden heidän epäuskonsa kautta saaneet;","Sillä niinkuin ette tekään muinen Jumalan päälle uskoneet, mutta olette nyt laupiuden heidän epäuskonsa kautta saaneet;"],[11,31,"Niin ei he ole myös nyt uskoneet sitä laupiutta, joka teille on tapahtunut, että heillekin laupius tapahtuis.","Niin ei he ole myös nyt uskoneet sitä laupiutta, joka teille on tapahtunut, että heillekin laupius tapahtuis."],[11,32,"Sillä Jumala on kaikki epäuskon alle sulkenut, että hän kaikkia armahtais.","Sillä Jumala on kaikki epäuskon alle sulkenut, että hän kaikkia armahtais."],[11,33,"Oi sitä Jumalan rikkauden, ja viisauden, ja tunnon syvyyttä! kuinka tutkimattomat ovat hänen tuomionsa ja käsittämättömät hänen tiensä!","Oi sitä Jumalan rikkauden, ja viisauden, ja tunnon syvyyttä! kuinka tutkimattomat ovat hänen tuomionsa ja käsittämättömät hänen tiensä!"],[11,34,"Sillä kuka on Herran mielen tietänyt? Eli kuka on hänen neuvonantajansa ollut?","Sillä kuka on Herran mielen tietänyt? Eli kuka on hänen neuvonantajansa ollut?"],[11,35,"Eli kuka on hänelle jotakin ennen antanut, jota hänelle pitäis jälleen maksettaman.","Eli kuka on hänelle jotakin ennen antanut, jota hänelle pitäis jälleen maksettaman."],[11,36,"Sillä hänestä ja hänen kauttansa ja hänessä ovat kaikki: hänelle olkoon kunnia ijankaikkisesti, amen!","Sillä hänestä ja hänen kauttansa ja hänessä ovat kaikki: hänelle olkoon kunnia ijankaikkisesti, amen!"],[12,1,"Niin neuvon minä teitä, rakkaat veljet, Jumalan sydämellisen laupiuden kautta, että te antaisitte teidän ruumiinne eläväksi, pyhäksi ja Jumalalle otolliseksi uhriksi, joka on teidän toimellinen jumalanpalveluksenne.","Niin neuvon minä teitä, rakkaat veljet, Jumalan sydämellisen laupiuden kautta, että te antaisitte teidän ruumiinne eläväksi, pyhäksi ja Jumalalle otolliseksi uhriksi, joka on teidän toimellinen jumalanpalveluksenne."],[12,2,"Ja älkäät sovittako teitänne tämän maailman muodon jälkeen, vaan muuttakaat teitänne teidän mielenne uudistuksen kautta, että te koettelisitte, mikä Jumalan hyvä, otollinen ja täydellinen tahto olis.","Ja älkäät sovittako teitänne tämän maailman muodon jälkeen, vaan muuttakaat teitänne teidän mielenne uudistuksen kautta, että te koettelisitte, mikä Jumalan hyvä, otollinen ja täydellinen tahto olis."],[12,3,"Sillä minä sanon siitä armosta, joka minulle annettu on, jokaiselle, joka teidän seassanne on, ettei yksikään itsestänsä enempää pitäisi kuin hänen tulee pitää; vaan pitäkään kohtuullisesti itsestänsä sen jälkeen kuin Jumala on kullekin uskon mitan jakanut.","Sillä minä sanon siitä armosta, joka minulle annettu on, jokaiselle, joka teidän seassanne on, ettei yksikään itsestänsä enempää pitäisi kuin hänen tulee pitää; vaan pitäkään kohtuullisesti itsestänsä sen jälkeen kuin Jumala on kullekin uskon mitan jakanut."],[12,4,"Sillä niinkuin meillä on yhdessä ruumiissa monta jäsentä, mutta ei kaikilla jäsenillä ole yhtäläinen työ,","Sillä niinkuin meillä on yhdessä ruumiissa monta jäsentä, mutta ei kaikilla jäsenillä ole yhtäläinen työ,"],[12,5,"Niin mekin olemme monta yksi ruumis Kristuksessa, mutta keskenämme olemme me toinen toisemme jäsenet.","Niin mekin olemme monta yksi ruumis Kristuksessa, mutta keskenämme olemme me toinen toisemme jäsenet."],[12,6,"Ja meillä ovat moninaiset lahjat siitä armosta, kuin meille annettu on. Jos jollakin on prophetia, niin olkoon uskon kanssa yhteinen.","Ja meillä ovat moninaiset lahjat siitä armosta, kuin meille annettu on. Jos jollakin on prophetia, niin olkoon uskon kanssa yhteinen."],[12,7,"Jos jollakin on joku virka, niin pitäkään virastansa vaarin. Jos joku opettaa, niin ottakaan opetuksestansa vaarin.","Jos jollakin on joku virka, niin pitäkään virastansa vaarin. Jos joku opettaa, niin ottakaan opetuksestansa vaarin."],[12,8,"Jos joku neuvoo, niin pitäkään neuvostansa vaarin. Jos joku antaa, niin antakaan yksinkertaisuudessa. Jos joku hallitsee, niin pitäkään siitä murheen. Jos joku armahtaa, niin tehkään sen ilolla,","Jos joku neuvoo, niin pitäkään neuvostansa vaarin. Jos joku antaa, niin antakaan yksinkertaisuudessa. Jos joku hallitsee, niin pitäkään siitä murheen. Jos joku armahtaa, niin tehkään sen ilolla,"],[12,9,"Olkoon rakkaus vilpitöin. Vihatkaat pahaa ja riippukaat kiinni hyvässä.","Olkoon rakkaus vilpitöin. Vihatkaat pahaa ja riippukaat kiinni hyvässä."],[12,10,"Veljellinen rakkaus olkoon sydämellinen teidän keskenänne. Ennättäkään toinen toisensa kunniaa tekemässä.","Veljellinen rakkaus olkoon sydämellinen teidän keskenänne. Ennättäkään toinen toisensa kunniaa tekemässä."],[12,11,"Älkäät olko hitaat töissänne. Olkaat palavat hengessä. Palvelkaat Herraa.","Älkäät olko hitaat töissänne. Olkaat palavat hengessä. Palvelkaat Herraa."],[12,12,"Olkaat toivossa iloiset, kärsivälliset murheessa. Olkaat alati rukouksissa.","Olkaat toivossa iloiset, kärsivälliset murheessa. Olkaat alati rukouksissa."],[12,13,"Jakakaat omanne pyhäin tarpeeksi. Ottakaat mielellänne huoneesen.","Jakakaat omanne pyhäin tarpeeksi. Ottakaat mielellänne huoneesen."],[12,14,"Siunatkaat vainollisianne: siunatkaat ja älkäät sadatelko.","Siunatkaat vainollisianne: siunatkaat ja älkäät sadatelko."],[12,15,"Iloitkaat iloisten kanssa, ja itkekäät itkeväisten kanssa.","Iloitkaat iloisten kanssa, ja itkekäät itkeväisten kanssa."],[12,16,"Olkaat keskenänne yksimieliset. Älkäät itsestänne paljon pitäkö, vaan pitäkäät teitänne nöyräin kaltaisena. Älkäät itsiänne ylen viisaina pitäkö.","Olkaat keskenänne yksimieliset. Älkäät itsestänne paljon pitäkö, vaan pitäkäät teitänne nöyräin kaltaisena. Älkäät itsiänne ylen viisaina pitäkö."],[12,17,"Älkäät kellenkään pahaa pahalla kostako. Ahkeroitkaat sitä, mikä kunniallinen on kaikkein ihmisten edessä.","Älkäät kellenkään pahaa pahalla kostako. Ahkeroitkaat sitä, mikä kunniallinen on kaikkein ihmisten edessä."],[12,18,"Jos mahdollinen on, niin paljo kuin teissä on, niin pitäkäät rauha kaikkein ihmisten kanssa.","Jos mahdollinen on, niin paljo kuin teissä on, niin pitäkäät rauha kaikkein ihmisten kanssa."],[12,19,"Älkäät itse kostako, minun rakkaani, vaan antakaat (Jumalan) vihan siaa saada. Sillä kirjoitettu on: minun on kosto, minä tahdon kostaa, sanoo Herra.","Älkäät itse kostako, minun rakkaani, vaan antakaat (Jumalan) vihan siaa saada. Sillä kirjoitettu on: minun on kosto, minä tahdon kostaa, sanoo Herra."],[12,20,"Sentähden, jos vihollises isoo, niin syötä häntä, ja jos hän janoo, niin juota häntä; sillä koskas tämän teet, niin sinä tuliset hiilet hänen päänsä päälle kokoot.","Sentähden, jos vihollises isoo, niin syötä häntä, ja jos hän janoo, niin juota häntä; sillä koskas tämän teet, niin sinä tuliset hiilet hänen päänsä päälle kokoot."],[12,21,"Älä anna sinuas voitettaa pahalta, vaan voita sinä paha hyvällä.","Älä anna sinuas voitettaa pahalta, vaan voita sinä paha hyvällä."],[13,1,"Jokainen olkoon esivallalle, jolla valta on, alamainen; sillä ei esivalta ole muutoin kuin Jumalalta: ne vallat, jotka ovat, Jumalalta ne säädetyt ovat.","Jokainen olkoon esivallalle, jolla valta on, alamainen; sillä ei esivalta ole muutoin kuin Jumalalta: ne vallat, jotka ovat, Jumalalta ne säädetyt ovat."],[13,2,"Sentähden jokainen, joka itsensä esivaltaa vastaan asettaa, se on Jumalan säätyä vastaan; mutta ne, jotka vastaan ovat, saavat tuomion päällensä.","Sentähden jokainen, joka itsensä esivaltaa vastaan asettaa, se on Jumalan säätyä vastaan; mutta ne, jotka vastaan ovat, saavat tuomion päällensä."],[13,3,"Sillä ne, jotka vallan päällä ovat, ei ole hyvintekiöille, vaan pahoille pelvoksi. Ellet tahdo esivaltaa peljätä, niin tee hyvää, ja sinä saat häneltä kiitoksen.","Sillä ne, jotka vallan päällä ovat, ei ole hyvintekiöille, vaan pahoille pelvoksi. Ellet tahdo esivaltaa peljätä, niin tee hyvää, ja sinä saat häneltä kiitoksen."],[13,4,"Sillä hän on Jumalan palvelia sinun hyväkses. Vaan jos sinä pahaa teet, niin pelkää; sillä ei hän miekkaa hukkaan kanna; sillä hän on Jumalan palvelia ja kostaja sille rangaistukseksi, joka pahaa tekee.","Sillä hän on Jumalan palvelia sinun hyväkses. Vaan jos sinä pahaa teet, niin pelkää; sillä ei hän miekkaa hukkaan kanna; sillä hän on Jumalan palvelia ja kostaja sille rangaistukseksi, joka pahaa tekee."],[13,5,"Sentähden tulee alamainen olla, ei ainoastaan vihan tähden, vaan myös omantunnon tähden.","Sentähden tulee alamainen olla, ei ainoastaan vihan tähden, vaan myös omantunnon tähden."],[13,6,"Sillä sentähden te myös veron maksatte; sillä he ovat Jumalan palveliat, joiden senkaltaisista tulee lukua pitää.","Sillä sentähden te myös veron maksatte; sillä he ovat Jumalan palveliat, joiden senkaltaisista tulee lukua pitää."],[13,7,"Niin antakaat siis kaikille, mitä te velvolliset olette: sille vero, jolle vero tulee; sille tulli, jolle tulli tulee; sille pelko, jolle pelko tulee; sille kunnia, jolle kunnia tulee.","Niin antakaat siis kaikille, mitä te velvolliset olette: sille vero, jolle vero tulee; sille tulli, jolle tulli tulee; sille pelko, jolle pelko tulee; sille kunnia, jolle kunnia tulee."],[13,8,"Älkäät kellenkään velvolliset olko, vaan ainoastaan että te toinen toistanne rakastatte; sillä joka toista rakastaa, se on täyttänyt lain.","Älkäät kellenkään velvolliset olko, vaan ainoastaan että te toinen toistanne rakastatte; sillä joka toista rakastaa, se on täyttänyt lain."],[13,9,"Sillä se: ei sinun pidä huorin tekemän; ei sinun pidä tappaman; ei sinun pidä varastaman; ei sinun pidä väärää todistusta sanoman; ei sinun pidä himoitseman, ja mitä muuta käskyä on, se tähän sanaan suljetaan: sinun pitää rakastaman lähimmäistäs niinkuin itsiäs.","Sillä se: ei sinun pidä huorin tekemän; ei sinun pidä tappaman; ei sinun pidä varastaman; ei sinun pidä väärää todistusta sanoman; ei sinun pidä himoitseman, ja mitä muuta käskyä on, se tähän sanaan suljetaan: sinun pitää rakastaman lähimmäistäs niinkuin itsiäs."],[13,10,"Ei rakkaus tee lähimmäiselle mitään pahaa; sentähden on rakkaus lain täyttämys.","Ei rakkaus tee lähimmäiselle mitään pahaa; sentähden on rakkaus lain täyttämys."],[13,11,"Ja että me sen tiedämme, nimittäin ajan, että nyt on aika unesta nousta; sillä meidän autuutemme on nyt lähempänä kuin silloin, kuin me uskoimme.","Ja että me sen tiedämme, nimittäin ajan, että nyt on aika unesta nousta; sillä meidän autuutemme on nyt lähempänä kuin silloin, kuin me uskoimme."],[13,12,"Yö on kulunut ja päivä on tullut; sentähden hyljätkäämme pimeyden työt ja pukekaamme meitämme valkeuden sota-aseilla.","Yö on kulunut ja päivä on tullut; sentähden hyljätkäämme pimeyden työt ja pukekaamme meitämme valkeuden sota-aseilla."],[13,13,"Vaeltakaamme soveliaasti, niinkuin päivällä: ei ylönsyömisessä, eikä juopumisessa, ei kammioissa, eikä haureudessa, ei riidassa ja kateudessa,","Vaeltakaamme soveliaasti, niinkuin päivällä: ei ylönsyömisessä, eikä juopumisessa, ei kammioissa, eikä haureudessa, ei riidassa ja kateudessa,"],[13,14,"Vaan pukekaat päällenne Herra Jesus Kristus ja älkäät holhoko ruumistannen haureuteen.","Vaan pukekaat päällenne Herra Jesus Kristus ja älkäät holhoko ruumistannen haureuteen."],[14,1,"Heikkouskoista korjatkaat, ei kamppausten riidoissa.","Heikkouskoista korjatkaat, ei kamppausten riidoissa."],[14,2,"Yksi kyllä uskoo saavansa kaikkinaista syödä, vaan heikko syö kaalia.","Yksi kyllä uskoo saavansa kaikkinaista syödä, vaan heikko syö kaalia."],[14,3,"Joka syö, älkään sitä katsoko ylön, joka ei syö; ja se, joka ei syö, älkään tuomitko sitä, joka syö; sillä Jumala on hänen ottanut vastaan.","Joka syö, älkään sitä katsoko ylön, joka ei syö; ja se, joka ei syö, älkään tuomitko sitä, joka syö; sillä Jumala on hänen ottanut vastaan."],[14,4,"Kuka sinä olet, joka toisen palveliaa tuomitse? Omalle isännällensä hän seisoo eli lankee. Mutta hän taidetaan ojentaa ylös; sillä Jumala on voimallinen häntä ojentamaan.","Kuka sinä olet, joka toisen palveliaa tuomitse? Omalle isännällensä hän seisoo eli lankee. Mutta hän taidetaan ojentaa ylös; sillä Jumala on voimallinen häntä ojentamaan."],[14,5,"Yksi eroittaa yhden päivän toisesta, toinen pitää kaikki päivät yhtäläisenä: jokainen olkoon vahva mielessänsä.","Yksi eroittaa yhden päivän toisesta, toinen pitää kaikki päivät yhtäläisenä: jokainen olkoon vahva mielessänsä."],[14,6,"Joka päivää tottelee, sen hän Herralle tekee; ja joka ei päivää tottele, se myös sen Herralle tekee. Joka syö, hän syö Herralle; sillä hän kiittää Jumalaa: ja joka ei syö, se ei syö Herralle, ja kiittää Jumalaa.","Joka päivää tottelee, sen hän Herralle tekee; ja joka ei päivää tottele, se myös sen Herralle tekee. Joka syö, hän syö Herralle; sillä hän kiittää Jumalaa: ja joka ei syö, se ei syö Herralle, ja kiittää Jumalaa."],[14,7,"Sillä ei yksikään meistä itsellensä elä, eikä yksikään itsellensä kuole.","Sillä ei yksikään meistä itsellensä elä, eikä yksikään itsellensä kuole."],[14,8,"Sillä jos me elämme niin me Herralle elämme; jos me kuolemme, niin me Herralle kuolemme. Sentähden joko me elämme tai kuolemme, niin me Herran omat olemme.","Sillä jos me elämme niin me Herralle elämme; jos me kuolemme, niin me Herralle kuolemme. Sentähden joko me elämme tai kuolemme, niin me Herran omat olemme."],[14,9,"Sillä sentähden on myös Kristus kuollut ja noussut ylös ja jälleen eläväksi tullut, että hän olis kuolleiden ja elävien Herra.","Sillä sentähden on myös Kristus kuollut ja noussut ylös ja jälleen eläväksi tullut, että hän olis kuolleiden ja elävien Herra."],[14,10,"Mutta miksi sinä veljes tuomitset? Eli miksi sinä veljes katsot ylön? sillä me asetetaan kaikki Kristuksen tuomio-istuimen eteen.","Mutta miksi sinä veljes tuomitset? Eli miksi sinä veljes katsot ylön? sillä me asetetaan kaikki Kristuksen tuomio-istuimen eteen."],[14,11,"Sillä kirjoitettu on: niin totta kuin minä elän, sanoo Herra, minua pitää kaikki polvet kumartaman, ja kaikki kielet pitää Jumalaa tunnustaman.","Sillä kirjoitettu on: niin totta kuin minä elän, sanoo Herra, minua pitää kaikki polvet kumartaman, ja kaikki kielet pitää Jumalaa tunnustaman."],[14,12,"Sentähden jokaisen meistä pitää edestänsä Jumalalle luvun tekemän.","Sentähden jokaisen meistä pitää edestänsä Jumalalle luvun tekemän."],[14,13,"Älkäämme siis tästedes toinen toistamme tuomitko, vaan tuomitkaat paremmin niin, ettei yksikään veljensä eteen pane loukkausta eli pahennusta.","Älkäämme siis tästedes toinen toistamme tuomitko, vaan tuomitkaat paremmin niin, ettei yksikään veljensä eteen pane loukkausta eli pahennusta."],[14,14,"Minä tiedän ja olen vahva Herrassa Jesuksessa, ettei mitään itsestänsä yhteistä ole, vaan joka jotakin yhteiseksi luulee, hänelle se on yhteinen.","Minä tiedän ja olen vahva Herrassa Jesuksessa, ettei mitään itsestänsä yhteistä ole, vaan joka jotakin yhteiseksi luulee, hänelle se on yhteinen."],[14,15,"Mutta jos sinun veljes sinun ruastas surulliseksi tulee, niin et sinä enään vaella rakkaudessa. Älä sitä ruallas kadota, jonka tähden Kristus on kuollut.","Mutta jos sinun veljes sinun ruastas surulliseksi tulee, niin et sinä enään vaella rakkaudessa. Älä sitä ruallas kadota, jonka tähden Kristus on kuollut."],[14,16,"Sentähden sovittakaat niin, ettei teidän hyvyyttänne laitettaisi.","Sentähden sovittakaat niin, ettei teidän hyvyyttänne laitettaisi."],[14,17,"Sillä ei Jumalan valtakunta ole ruoka ja juoma, mutta vanhurskaus, ja rauha, ja ilo Pyhässä Hengessä.","Sillä ei Jumalan valtakunta ole ruoka ja juoma, mutta vanhurskaus, ja rauha, ja ilo Pyhässä Hengessä."],[14,18,"Sillä joka niissä Kristusta palvelee, hän on Jumalalle otollinen ja ihmisille kelvollinen.","Sillä joka niissä Kristusta palvelee, hän on Jumalalle otollinen ja ihmisille kelvollinen."],[14,19,"Sentähden noudattakaamme niitä, mitkä rauhaan sopivat, ja sitä, mikä keskenämme parannukseksi tulee.","Sentähden noudattakaamme niitä, mitkä rauhaan sopivat, ja sitä, mikä keskenämme parannukseksi tulee."],[14,20,"Älä ruan tähden Jumalan työtä turmele. Kaikki tosin ovat puhtaat; vaan sille ihmiselle on se paha, joka syö omantuntonsa pahennuksen kanssa.","Älä ruan tähden Jumalan työtä turmele. Kaikki tosin ovat puhtaat; vaan sille ihmiselle on se paha, joka syö omantuntonsa pahennuksen kanssa."],[14,21,"Se on hyvä, ettet lihaa söisi etkä viinaa joisi eli jotakin, josta veljes loukkaantuu, taikka pahenee, elikkä heikoksi tulee.","Se on hyvä, ettet lihaa söisi etkä viinaa joisi eli jotakin, josta veljes loukkaantuu, taikka pahenee, elikkä heikoksi tulee."],[14,22,"Jos sinulla on usko, niin pidä se itsessäs Jumalan edessä. Autuas on, joka ei tee itsellensä omaatuntoa niissä, mitkä hän koettelee.","Jos sinulla on usko, niin pidä se itsessäs Jumalan edessä. Autuas on, joka ei tee itsellensä omaatuntoa niissä, mitkä hän koettelee."],[14,23,"Mutta joka siitä epäilee ja kuitenkin syö, se on kadotettu; sillä ei hän syönyt uskossa, mutta kaikki, mikä ei uskosta ole, se on synti.","Mutta joka siitä epäilee ja kuitenkin syö, se on kadotettu; sillä ei hän syönyt uskossa, mutta kaikki, mikä ei uskosta ole, se on synti."],[15,1,"Mutta meidän, jotka väkevät olemme, tulee heikkoin voimattomuutta kärsiä, eikä itsellemme kelvata.","Mutta meidän, jotka väkevät olemme, tulee heikkoin voimattomuutta kärsiä, eikä itsellemme kelvata."],[15,2,"Niin jokainen meistä kelvatkoon lähimmäisellensä siinä, mikä hyvä on, parannukseksi.","Niin jokainen meistä kelvatkoon lähimmäisellensä siinä, mikä hyvä on, parannukseksi."],[15,3,"Sillä ei Kristuskaan itsellensä kelvannut, vaan niinkuin kirjoitettu on: heidän pilkkansa, jotka sinua pilkkasivat, lankesivat minun päälleni.","Sillä ei Kristuskaan itsellensä kelvannut, vaan niinkuin kirjoitettu on: heidän pilkkansa, jotka sinua pilkkasivat, lankesivat minun päälleni."],[15,4,"Sillä mitä ennen kirjoitettu on, se on meille opiksi kirjoitettu, että meillä kärsivällisyyden ja Raamattuin lohdutuksen kautta toivo olis.","Sillä mitä ennen kirjoitettu on, se on meille opiksi kirjoitettu, että meillä kärsivällisyyden ja Raamattuin lohdutuksen kautta toivo olis."],[15,5,"Mutta kärsivällisyyden ja lohdutuksen Jumala antakoon teille, että te keskenänne yksimieliset olisitte Jesuksen Kristuksen perään:","Mutta kärsivällisyyden ja lohdutuksen Jumala antakoon teille, että te keskenänne yksimieliset olisitte Jesuksen Kristuksen perään:"],[15,6,"Että te yksimielisesti yhdestä suusta kiittäisitte Jumalaa ja meidän Herran Jesuksen Kristuksen Isää.","Että te yksimielisesti yhdestä suusta kiittäisitte Jumalaa ja meidän Herran Jesuksen Kristuksen Isää."],[15,7,"Sentähden korjatkaat toinen toistanne, niinkuin Kristuskin on meitä Jumalan kunniaksi korjannut.","Sentähden korjatkaat toinen toistanne, niinkuin Kristuskin on meitä Jumalan kunniaksi korjannut."],[15,8,"Mutta minä sanon: Jesus Kristus on ollut ympärileikkauksen palvelia Jumalan totuuden tähden, vahvistamaan sitä lupausta, joka isille tapahtunut oli.","Mutta minä sanon: Jesus Kristus on ollut ympärileikkauksen palvelia Jumalan totuuden tähden, vahvistamaan sitä lupausta, joka isille tapahtunut oli."],[15,9,"Mutta että pakanat laupiuden edestä Jumalaa kiittäisivät, niinkuin kirjoitettu on: sentähden kiitän minä sinua pakanain seassa ja veisaan sinun nimelles.","Mutta että pakanat laupiuden edestä Jumalaa kiittäisivät, niinkuin kirjoitettu on: sentähden kiitän minä sinua pakanain seassa ja veisaan sinun nimelles."],[15,10,"Ja taas hän sanoo: iloitkaat pakanat hänen kansansa kanssa!","Ja taas hän sanoo: iloitkaat pakanat hänen kansansa kanssa!"],[15,11,"Ja taas: kiittäkäät Herraa, kaikki pakanat, ja kaikki kansa ylistäkään häntä!","Ja taas: kiittäkäät Herraa, kaikki pakanat, ja kaikki kansa ylistäkään häntä!"],[15,12,"Ja taas sanoo Jesaias: sen pitää oleman Jessen juuren, joka on nouseva pakanoita hallitsemaan, jonka päälle pakanat toivoman pitää.","Ja taas sanoo Jesaias: sen pitää oleman Jessen juuren, joka on nouseva pakanoita hallitsemaan, jonka päälle pakanat toivoman pitää."],[15,13,"Mutta toivon Jumala täyttäköön teitä kaikella riemulla ja rauhalla uskossa, että teillä Pyhän Hengen voiman kautta yltäkylläinen toivo olis.","Mutta toivon Jumala täyttäköön teitä kaikella riemulla ja rauhalla uskossa, että teillä Pyhän Hengen voiman kautta yltäkylläinen toivo olis."],[15,14,"Mutta minä tiedän hyvästi, rakkaat veljeni, teistä, että te olette hyvyyttä täynnä, kaikella tuntemisella täytetyt, että te voitte toinen toistanne neuvoa.","Mutta minä tiedän hyvästi, rakkaat veljeni, teistä, että te olette hyvyyttä täynnä, kaikella tuntemisella täytetyt, että te voitte toinen toistanne neuvoa."],[15,15,"Minä olen kuitenkin puolittain rohkiasti teidän tykönne, rakkaat veljet, kirjoittanut, niinkuin muistuttain teille sen armon puolesta, joka minulle Jumalalta on annettu.","Minä olen kuitenkin puolittain rohkiasti teidän tykönne, rakkaat veljet, kirjoittanut, niinkuin muistuttain teille sen armon puolesta, joka minulle Jumalalta on annettu."],[15,16,"Että minun pitää oleman pakanain seassa Jesuksen Kristuksen palvelian, Jumalan evankeliumia uhraamassa, että pakanatkin olisivat Jumalalle otollinen uhri, Pyhän Hengen kautta pyhitetty.","Että minun pitää oleman pakanain seassa Jesuksen Kristuksen palvelian, Jumalan evankeliumia uhraamassa, että pakanatkin olisivat Jumalalle otollinen uhri, Pyhän Hengen kautta pyhitetty."],[15,17,"Sentähden minulla on se, josta minä Jesuksessa Kristuksessa kerskaan, niissä mitkä Jumalan ovat.","Sentähden minulla on se, josta minä Jesuksessa Kristuksessa kerskaan, niissä mitkä Jumalan ovat."],[15,18,"Sillä en minä rohkene mitään puhua niistä, mitä ei Kristus minun kauttani vaikuttanut pakanain kuuliaisuudeksi, sanalla ja työllä,","Sillä en minä rohkene mitään puhua niistä, mitä ei Kristus minun kauttani vaikuttanut pakanain kuuliaisuudeksi, sanalla ja työllä,"],[15,19,"Merkkien ja ihmeiden voimalla, Jumalan Hengen väellä; niin että minä hamasta Jerusalemista ja niissä ympäri Illyrikoon asti olen kaikki Kristuksen evankeliumilla täyttänyt.","Merkkien ja ihmeiden voimalla, Jumalan Hengen väellä; niin että minä hamasta Jerusalemista ja niissä ympäri Illyrikoon asti olen kaikki Kristuksen evankeliumilla täyttänyt."],[15,20,"Ja minä olen ollut ahkera evankeliumia saarnaamaan, joissa Kristuksen nimi ei mainittu ollut, etten minä muukalaisen perustuksen päälle rakentaisi;","Ja minä olen ollut ahkera evankeliumia saarnaamaan, joissa Kristuksen nimi ei mainittu ollut, etten minä muukalaisen perustuksen päälle rakentaisi;"],[15,21,"Vaan niinkuin kirjoitettu on: joille ei ensinkään hänestä julistettu ollut, niiden pitää sen näkemän, ja jotka ei kuulleet ole, niiden pitää ymmärtämän.","Vaan niinkuin kirjoitettu on: joille ei ensinkään hänestä julistettu ollut, niiden pitää sen näkemän, ja jotka ei kuulleet ole, niiden pitää ymmärtämän."],[15,22,"Sentähden myös minä olen usein estetty teidän tykönne tulemasta.","Sentähden myös minä olen usein estetty teidän tykönne tulemasta."],[15,23,"Mutta nyt, ettei minulla ole näissä maakunnissa enempi siaa ja minä olen jo monta vuotta halainnut teidän tykönne tulla,","Mutta nyt, ettei minulla ole näissä maakunnissa enempi siaa ja minä olen jo monta vuotta halainnut teidän tykönne tulla,"],[15,24,"Sentähden kuin minä Hispaniaan vaellan, niin minä tulen teidän tykönne; sillä minä toivon, että kuin minä sen kautta matkustan, niin minä saan teidät nähdä, ja niin teiltä sinne saatettaisiin; kuitenkin, että minä ennen saisin kerran minuni teistä ilahuttaa.","Sentähden kuin minä Hispaniaan vaellan, niin minä tulen teidän tykönne; sillä minä toivon, että kuin minä sen kautta matkustan, niin minä saan teidät nähdä, ja niin teiltä sinne saatettaisiin; kuitenkin, että minä ennen saisin kerran minuni teistä ilahuttaa."],[15,25,"Mutta nyt minä vaellan Jerusalemiin pyhille palvelusta tekemään;","Mutta nyt minä vaellan Jerusalemiin pyhille palvelusta tekemään;"],[15,26,"Sillä ne Makedoniasta ja Akajasta ovat mielellänsä Jerusalemin köyhiä pyhiä varten yhteisen avun koonneet.","Sillä ne Makedoniasta ja Akajasta ovat mielellänsä Jerusalemin köyhiä pyhiä varten yhteisen avun koonneet."],[15,27,"He ovat sen mielellänsä tehneet, niinkuin he siihen heille velkapäätkin ovat; sillä jos pakanat ovat heidän hengellisestä tavarastansa osallisiksi tulleet, niin on kohtuullinen, että he myös heitä ruumiillisella tavarallansa palvelevat.","He ovat sen mielellänsä tehneet, niinkuin he siihen heille velkapäätkin ovat; sillä jos pakanat ovat heidän hengellisestä tavarastansa osallisiksi tulleet, niin on kohtuullinen, että he myös heitä ruumiillisella tavarallansa palvelevat."],[15,28,"Kuin minä siis sen asian päättänyt olen ja heille tämän hedelmän lukinnut, tahdon minä teidän kauttannen Hispaniaan palata.","Kuin minä siis sen asian päättänyt olen ja heille tämän hedelmän lukinnut, tahdon minä teidän kauttannen Hispaniaan palata."],[15,29,"Mutta minä tiedän, kuin minä teidän tykönne tulen, että minä tulen Kristuksen evankeliumin täydellisellä siunauksella.","Mutta minä tiedän, kuin minä teidän tykönne tulen, että minä tulen Kristuksen evankeliumin täydellisellä siunauksella."],[15,30,"Mutta minä neuvon teitä, rakkaat veljet, meidän Herran Jesuksen Kristuksen kautta ja Hengen rakkauden kautta, että te minun kanssani kilvoittelisitte rukouksissa minun edestäni Jumalan tykö:","Mutta minä neuvon teitä, rakkaat veljet, meidän Herran Jesuksen Kristuksen kautta ja Hengen rakkauden kautta, että te minun kanssani kilvoittelisitte rukouksissa minun edestäni Jumalan tykö:"],[15,31,"Että minä Juudeassa epäuskoisista pelastettaisiin, ja että minun palvelukseni Jerusalemissa olis pyhille otollinen;","Että minä Juudeassa epäuskoisista pelastettaisiin, ja että minun palvelukseni Jerusalemissa olis pyhille otollinen;"],[15,32,"Että minä ilolla teidän tykönne tulisin Jumalan tahdon kautta, ja minuani ynnä teidän kanssanne virvoittaisin.","Että minä ilolla teidän tykönne tulisin Jumalan tahdon kautta, ja minuani ynnä teidän kanssanne virvoittaisin."],[15,33,"Mutta rauhan Jumala olkoon teidän kaikkein kanssanne! Amen.","Mutta rauhan Jumala olkoon teidän kaikkein kanssanne! Amen."],[16,1,"Minä annan teidän haltuunne Pheben, meidän sisaremme, joka on Kenkrean seurakunnan palveluspiika:","Minä annan teidän haltuunne Pheben, meidän sisaremme, joka on Kenkrean seurakunnan palveluspiika:"],[16,2,"Että te häntä ottaisitte vastaan Herrassa, niinkuin pyhäin sopii. Ja olkaat hänelle kaikissa asioissa avulliset, joissa hän teitä tarvitsee; sillä hän on monelle avullinen ollut ja itse minulle.","Että te häntä ottaisitte vastaan Herrassa, niinkuin pyhäin sopii. Ja olkaat hänelle kaikissa asioissa avulliset, joissa hän teitä tarvitsee; sillä hän on monelle avullinen ollut ja itse minulle."],[16,3,"Tervehtikäät Priskillaa ja Akvilaa, minun auttajiani Kristuksessa Jesuksessa,","Tervehtikäät Priskillaa ja Akvilaa, minun auttajiani Kristuksessa Jesuksessa,"],[16,4,"(Jotka ovat kaulansa minun henkeni tähden alttiiksi antaneet: joita en minä ainoasti kiitä, vaan kaikki pakanainkin seurakunnat.)","(Jotka ovat kaulansa minun henkeni tähden alttiiksi antaneet: joita en minä ainoasti kiitä, vaan kaikki pakanainkin seurakunnat.)"],[16,5,"Niin myös sitä seurakuntaa, joka heidän huoneessansa on. Tervehtikäät Epenetusta, minun rakkaintani, joka on Akajasta uutinen Kristuksessa.","Niin myös sitä seurakuntaa, joka heidän huoneessansa on. Tervehtikäät Epenetusta, minun rakkaintani, joka on Akajasta uutinen Kristuksessa."],[16,6,"Tervehtikäät Mariaa, joka paljon vaivaa meistä näki.","Tervehtikäät Mariaa, joka paljon vaivaa meistä näki."],[16,7,"Tervehtikäät Andronikusta ja Juniaa, minun lankojani ja kanssavankejani, jotka ovat kuuluisat apostolien seassa, jotka myös olivat ennen minua Kristuksessa.","Tervehtikäät Andronikusta ja Juniaa, minun lankojani ja kanssavankejani, jotka ovat kuuluisat apostolien seassa, jotka myös olivat ennen minua Kristuksessa."],[16,8,"Tervehtikäät Ampliaa, minun rakastani Herrassa.","Tervehtikäät Ampliaa, minun rakastani Herrassa."],[16,9,"Tervehtikäät Urbanusta, meidän auttajaamme Kristuksessa, ja Stakya, minun rakastani.","Tervehtikäät Urbanusta, meidän auttajaamme Kristuksessa, ja Stakya, minun rakastani."],[16,10,"Tervehtikäät Apellesta, joka on koeteltu Kristuksessa. Tervehtikäät Aristobulin perhettä.","Tervehtikäät Apellesta, joka on koeteltu Kristuksessa. Tervehtikäät Aristobulin perhettä."],[16,11,"Tervehtikäät Herodionia, minun lankoani. Tervehtikäät Narkissuksen perhettä, jotka ovat Herrassa.","Tervehtikäät Herodionia, minun lankoani. Tervehtikäät Narkissuksen perhettä, jotka ovat Herrassa."],[16,12,"Tervehtikäät Tryphenaa ja Tryphosaa, jotka työtä tekevät Herrassa. Tervehtikäät Persistä, minun rakastani, joka paljon työtä tehnyt on Herrassa.","Tervehtikäät Tryphenaa ja Tryphosaa, jotka työtä tekevät Herrassa. Tervehtikäät Persistä, minun rakastani, joka paljon työtä tehnyt on Herrassa."],[16,13,"Tervehtikäät Rufusta, valittua Herrassa, ja hänen ja minun äitiäni.","Tervehtikäät Rufusta, valittua Herrassa, ja hänen ja minun äitiäni."],[16,14,"Tervehtikäät Asynkritusta ja Phlegonia, Hermasta, Patrobasta, Hermestä ja veljiä, jotka heidän kanssansa ovat.","Tervehtikäät Asynkritusta ja Phlegonia, Hermasta, Patrobasta, Hermestä ja veljiä, jotka heidän kanssansa ovat."],[16,15,"Tervehtikäät Philologusta ja Juliaa, Nereusta, ja hänen sisartansa, ja Olympaa, ja kaikkia pyhiä, jotka ovat heidän kanssansa.","Tervehtikäät Philologusta ja Juliaa, Nereusta, ja hänen sisartansa, ja Olympaa, ja kaikkia pyhiä, jotka ovat heidän kanssansa."],[16,16,"Tervehtikäät teitänne keskenänne pyhällä suunantamisella. Kristuksen seurakunnat tervehtivät teitä.","Tervehtikäät teitänne keskenänne pyhällä suunantamisella. Kristuksen seurakunnat tervehtivät teitä."],[16,17,"Mutta minä neuvon teitä, rakkaat veljet, että te kavahtaisitte eripuraisuuden ja pahennuksen matkaan saattajia sitä oppia vastaan, jonka te oppineet olette: ja välttäkäät niitä.","Mutta minä neuvon teitä, rakkaat veljet, että te kavahtaisitte eripuraisuuden ja pahennuksen matkaan saattajia sitä oppia vastaan, jonka te oppineet olette: ja välttäkäät niitä."],[16,18,"Sillä ei senkaltaiset Herraa Jesusta Kristusta palvele, vaan omaa vatsaansa ja viettelevät makeilla puheillansa ja liehakoitsemisellansa yksinkertaisten sydämet.","Sillä ei senkaltaiset Herraa Jesusta Kristusta palvele, vaan omaa vatsaansa ja viettelevät makeilla puheillansa ja liehakoitsemisellansa yksinkertaisten sydämet."],[16,19,"Sillä teidän kuuliaisuutenne on kaikille julistettu, jonka tähden minä iloitsen teidän ylitsenne. Mutta minä tahdon, että teidän pitää hyvässä viisaat oleman ja pahuudessa yksinkertaiset.","Sillä teidän kuuliaisuutenne on kaikille julistettu, jonka tähden minä iloitsen teidän ylitsenne. Mutta minä tahdon, että teidän pitää hyvässä viisaat oleman ja pahuudessa yksinkertaiset."],[16,20,"Mutta rauhan Jumala on tallaava saatanan pian teidän jalkainne alle. Meidän Herran Jesuksen Kristuksen armo olkoon teidän kanssanne! Amen.","Mutta rauhan Jumala on tallaava saatanan pian teidän jalkainne alle. Meidän Herran Jesuksen Kristuksen armo olkoon teidän kanssanne! Amen."],[16,21,"Teitä tervehtivät Timoteus, minun auttajani, ja Lukius, ja Jason ja Sosipater, minun lankoni.","Teitä tervehtivät Timoteus, minun auttajani, ja Lukius, ja Jason ja Sosipater, minun lankoni."],[16,22,"Minä Tertius, joka tämän lähetyskirjan kirjoitin, tervehdin teitä Herrassa.","Minä Tertius, joka tämän lähetyskirjan kirjoitin, tervehdin teitä Herrassa."],[16,23,"Teitä tervehtii Gajus, minun ja kaiken seurakunnan holhoja. Teitä tervehtii Erastus, kaupungin rahanhaltia, ja Kvartus veli.","Teitä tervehtii Gajus, minun ja kaiken seurakunnan holhoja. Teitä tervehtii Erastus, kaupungin rahanhaltia, ja Kvartus veli."],[16,24,"Meidän Herran Jesuksen Kristuksen armo olkoon teidän kaikkein kanssanne! Amen.","Meidän Herran Jesuksen Kristuksen armo olkoon teidän kaikkein kanssanne! Amen."],[16,25,"Mutta hänelle, joka voi teitä vahvistaa minun evankeliumini ja Jesuksen Kristuksen saarnan jälkeen, sen salaisuuden ilmestyksen jälkeen, joka ijäisiin aikoihin on salattu ollut,","Mutta hänelle, joka voi teitä vahvistaa minun evankeliumini ja Jesuksen Kristuksen saarnan jälkeen, sen salaisuuden ilmestyksen jälkeen, joka ijäisiin aikoihin on salattu ollut,"],[16,26,"Mutta nyt ilmoitettu ja tiettäväksi tehty prophetain Raamattuin kautta, ijankaikkisen Jumalan käskyn jälkeen, uskon kuuliaisuudeksi kaikkein pakanain seassa:","Mutta nyt ilmoitettu ja tiettäväksi tehty prophetain Raamattuin kautta, ijankaikkisen Jumalan käskyn jälkeen, uskon kuuliaisuudeksi kaikkein pakanain seassa:"],[16,27,"Jumalalle, joka yksinänsä viisas on, olkoon kunnia Jesuksen Kristuksen kautta ijankaikkisesti! Amen!","Jumalalle, joka yksinänsä viisas on, olkoon kunnia Jesuksen Kristuksen kautta ijankaikkisesti! Amen!"]]}};